### 6. DRM Routes (routes/drm.js)
```javascript
const express = require('express');
const router = express.Router();
const DRMKey = require('../models/DRMKey');
const Video = require('../models/Video');
const auth = require('../middleware/auth');

// Generate DRM license
router.post('/license', auth, async (req, res) => {
  try {
    const { videoId, keyId, userId } = req.body;

    // Verify user has access to video
    // Implement your access control logic here

    const drmKey = await DRMKey.findOne({ videoId, keyId });

    if (!drmKey) {
      return res.status(404).json({ error: 'DRM key not found' });
    }

    // Generate license response based on key system
    let licenseResponse;

    switch (drmKey.keySystem) {
      case 'widevine':
        licenseResponse = generateWidevineLicense(drmKey);
        break;
      case 'playready':
        licenseResponse = generatePlayReadyLicense(drmKey);
        break;
      case 'fairplay':
        licenseResponse = generateFairPlayLicense(drmKey);
        break;
      default:
        return res.status(400).json({ error: 'Unsupported DRM system' });
    }

    res.json(licenseResponse);
  } catch (error) {
    console.error('License generation error:', error);
    res.status(500).json({ error: 'Server error' });
  }
});

// Widevine license generation
function generateWidevineLicense(drmKey) {
  return {
    payload: Buffer.from(JSON.stringify({
      contentKey: drmKey.contentKey,
      keyId: drmKey.keyId
    })).toString('base64'),
    content_id: drmKey.keyId
  };
}

// PlayReady license generation
function generatePlayReadyLicense(drmKey) {
  // Implement PlayReady license generation
  return { license: 'playready-license-data' };
}

// FairPlay license generation
function generateFairPlayLicense(drmKey) {
  // Implement FairPlay license generation
  return { license: 'fairplay-license-data' };
}

module.exports = router;
```

### 7. Video Encryption Service (services/videoEncryption.js)
```javascript
const ffmpeg = require('fluent-ffmpeg');
const crypto = require('crypto');
const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');

class VideoEncryptionService {
  constructor() {
    this.s3 = new AWS.S3({
      accessKeyId: process.env.AWS_ACCESS_KEY,
      secretAccessKey: process.env.AWS_SECRET_KEY,
      region: process.env.AWS_REGION
    });
  }

  // Encrypt video with DRM
  async encryptVideo(inputPath, outputDir, videoId) {
    return new Promise(async (resolve, reject) => {
      try {
        // Generate encryption keys
        const keys = await this.generateDRMKeys(videoId);

        // Create encryption key file for FFmpeg
        const keyFile = path.join(outputDir, 'encryption.key');
        const keyInfoFile = path.join(outputDir, 'keyinfo.txt');

        // Write key info file for HLS encryption
        const keyInfo = `${this.getKeyUri(keys.keyId)}\n${keyFile}\n${keys.keyHex}`;
        fs.writeFileSync(keyInfoFile, keyInfo);
        fs.writeFileSync(keyFile, Buffer.from(keys.keyHex, 'hex'));

        // Encrypt video using HLS with AES-128
        const outputPattern = path.join(outputDir, 'video_%v.m3u8');

        ffmpeg(inputPath)
          .outputOptions([
            '-hls_time 10',
            '-hls_playlist_type vod',
            '-hls_key_info_file ' + keyInfoFile,
            '-hls_segment_filename ' + path.join(outputDir, 'segment_%v_%d.ts'),
            '-master_pl_name master.m3u8'
          ])
          .output(outputPattern)
          .on('end', async () => {
            // Upload encrypted segments to S3
            await this.uploadToS3(outputDir, videoId);

            // Save DRM keys to database
            await this.saveDRMKeys(videoId, keys);

            resolve({
              success: true,
              manifestUrl: `https://${process.env.S3_BUCKET}.s3.amazonaws.com/${videoId}/master.m3u8`,
              keyId: keys.keyId
            });
          })
          .on('error', reject)
          .run();
      } catch (error) {
        reject(error);
      }
    });
  }

  async generateDRMKeys(videoId) {
    // Generate random key and key ID
    const keyId = crypto.randomBytes(16).toString('hex');
    const key = crypto.randomBytes(16); // 128-bit key
    const keyHex = key.toString('hex');

    return {
      keyId,
      keyHex,
      contentKey: key.toString('base64')
    };
  }

  getKeyUri(keyId) {
    return `/api/drm/key/${keyId}`;
  }

  async uploadToS3(localDir, videoId) {
    const files = fs.readdirSync(localDir);

    for (const file of files) {
      const filePath = path.join(localDir, file);
      const fileStream = fs.createReadStream(filePath);

      const params = {
        Bucket: process.env.S3_BUCKET,
        Key: `${videoId}/${file}`,
        Body: fileStream,
        ContentType: this.getContentType(file)
      };

      await this.s3.upload(params).promise();
    }
  }

  getContentType(filename) {
    if (filename.endsWith('.m3u8')) return 'application/vnd.apple.mpegurl';
    if (filename.endsWith('.ts')) return 'video/MP2T';
    if (filename.endsWith('.mp4')) return 'video/mp4';
    return 'application/octet-stream';
  }

  async saveDRMKeys(videoId, keys) {
    // Save to database
    const DRMKey = require('../models/DRMKey');

    await DRMKey.create({
      videoId,
      keyId: keys.keyId,
      contentKey: keys.contentKey,
      keySystem: 'widevine', // Add support for others as needed
      licenseUrl: `/api/drm/license`
    });
  }
}

module.exports = new VideoEncryptionService();
```

### 8. Frontend Video Player (React Component)
```jsx
import React, { useRef, useEffect } from 'react';
import { getJWToken } from './auth';
import './VideoPlayer.css';

const VideoPlayer = ({ videoId, title, poster }) => {
  const videoRef = useRef(null);
  const playerRef = useRef(null);

  useEffect(() => {
    const initializePlayer = async () => {
      if (window.ShakaPlayer) {
        const player = new window.ShakaPlayer.Player(videoRef.current);
        playerRef.current = player;

        // Configure DRM
        player.configure({
          drm: {
            servers: {
              'com.widevine.alpha': `/api/drm/license`,
              'com.microsoft.playready': `/api/drm/license`
            }
          }
        });

        try {
          // Get video manifest
          const response = await fetch(`/api/stream/manifest/${videoId}`, {
            headers: {
              'Authorization': `Bearer ${getJWToken()}`
            }
          });

          const data = await response.json();

          // Load encrypted stream
          await player.load(data.manifestUrl);
        } catch (error) {
          console.error('Error loading video:', error);
        }
      }
    };

    initializePlayer();

    return () => {
      if (playerRef.current) {
        playerRef.current.destroy();
      }
    };
  }, [videoId]);

  return (
    <div className="video-player-container">
      <div className="video-wrapper">
        <video
          ref={videoRef}
          controls
          crossOrigin="anonymous"
          poster={poster}
          className="video-element"
        >
          Your browser does not support HTML5 video.
        </video>
      </div>
      <div className="video-info">
        <h2>{title}</h2>
        <div className="player-controls">
          <button className="control-btn" onClick={() => videoRef.current.play()}>
            Play
          </button>
          <button className="control-btn" onClick={() => videoRef.current.pause()}>
            Pause
          </button>
          <input
            type="range"
            min="0"
            max="100"
            className="volume-slider"
            onChange={(e) => videoRef.current.volume = e.target.value / 100}
          />
        </div>
      </div>
    </div>
  );
};

export default VideoPlayer;
```

