## الخطوة 2: Authentication & Authorization

### 1. افتح Apps Script وأضف الكود ده في ملف جديد اسمه `Auth.gs`

```javascript
/**
 * التحقق من هوية المستخدم وصلاحياته
 */
function loginUser(email) {
  if (!email) {
    return { ok: false, code: 'NO_EMAIL', message: 'لم يتم إرسال البريد الإلكتروني' };
  }

  const accounts = getSheetData('Accounts');
  const account = accounts.find(a => 
    String(a.Email).toLowerCase().trim() === String(email).toLowerCase().trim()
  );

  if (!account) {
    logAction(email, 'LOGIN_FAILED', 'Account', '', 'الحساب غير موجود', 'Access Denied');
    return { ok: false, code: 'ACCESS_DENIED', message: 'Access Denied - الحساب غير موجود في النظام' };
  }

  if (String(account.Status).toLowerCase() !== 'active') {
    logAction(email, 'LOGIN_FAILED', 'Account', account.AccountID, 'الحساب معطل', 'Account Disabled');
    return { ok: false, code: 'ACCOUNT_DISABLED', message: 'Account Disabled - الحساب معطل' };
  }

  // جلب بيانات الشخص المرتبط إن وجد
  let person = null;
  if (account.PersonID) {
    const people = getSheetData('People');
    person = people.find(p => String(p.PersonID) === String(account.PersonID)) || null;
  }

  // حساب الأدوار المتاحة
  const roles = getRolesFromAccount(account);

  logAction(email, 'LOGIN_SUCCESS', 'Account', account.AccountID, 'تسجيل دخول ناجح', 'Success');

  return {
    ok: true,
    account: {
      AccountID: account.AccountID,
      Email: account.Email,
      Role: account.Role,
      PersonID: account.PersonID,
      Status: account.Status
    },
    roles: roles,
    person: person
  };
}

/**
 * استخراج الأدوار من حقل Role
 * ممكن يكون: "Admin" أو "Admin,Scanner" أو "Owner"
 */
function getRolesFromAccount(account) {
  if (!account || !account.Role) return [];
  return String(account.Role)
    .split(',')
    .map(r => r.trim())
    .filter(r => ['Owner', 'Admin', 'Scanner', 'User'].includes(r));
}

/**
 * التحقق من صلاحية معينة
 */
function hasPermission(email, requiredRole) {
  const result = loginUser(email);
  if (!result.ok) return false;
  return result.roles.includes(requiredRole) || result.roles.includes('Owner');
}

/**
 * التحقق من أن المستخدم Owner
 */
function isOwner(email) {
  const result = loginUser(email);
  return result.ok && result.roles.includes('Owner');
}

/**
 * التحقق من أن المستخدم Admin أو أعلى
 */
function isAdminOrAbove(email) {
  const result = loginUser(email);
  if (!result.ok) return false;
  return result.roles.includes('Admin') || result.roles.includes('Owner');
}

/**
 * تسجيل العمليات في Logs
 */
function logAction(userEmail, action, targetType, targetID, details, result) {
  try {
    appendRow('Logs', {
      LogID: generateId('LOG'),
      UserEmail: userEmail || 'unknown',
      Action: action || '',
      TargetType: targetType || '',
      TargetID: targetID || '',
      Details: details || '',
      Timestamp: new Date(),
      Result: result || ''
    });
  } catch (e) {
    console.error('Log failed:', e);
  }
}
```

