### 3. اعمل ملف جديد اسمه `Dashboard.gs`

في Apps Script، اضغط علامة `+` جنب Files → **Script** → سمّيه `Dashboard`

والصق الكود ده:

```javascript
/**
 * إحصائيات الـDashboard الرئيسية
 */
function getDashboardStats(email) {
  // تحقق من الصلاحية
  const auth = loginUser(email);
  if (!auth.ok) {
    return { ok: false, code: auth.code, message: auth.message };
  }

  const allowedRoles = ['Owner', 'Admin'];
  const hasAccess = auth.roles.some(r => allowedRoles.includes(r));
  if (!hasAccess) {
    return { ok: false, code: 'FORBIDDEN', message: 'ليس لديك صلاحية الوصول' };
  }

  try {
    const people = getSheetData('People');
    const meetings = getSheetData('Meetings');
    const attendance = getSheetData('Attendance');
    const settings = getSettingsObject();

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // عدد الأشخاص النشطين
    const activePeople = people.filter(p => 
      String(p.Status).toLowerCase() === 'active'
    ).length;

    // عدد الاجتماعات
    const totalMeetings = meetings.filter(m => 
      String(m.Status).toLowerCase() !== 'archived'
    ).length;

    // حضور اليوم
    const todayAttendance = attendance.filter(a => {
      const scanDate = new Date(a.ScanTime);
      scanDate.setHours(0, 0, 0, 0);
      return scanDate.getTime() === today.getTime();
    }).length;

    // نسبة الحضور (اليوم)
    const attendanceRate = activePeople > 0
      ? Math.round((todayAttendance / activePeople) * 100)
      : 0;

    // حالة النظام
    const systemStatus = settings.SystemStatus || 'Active';

    return {
      ok: true,
      stats: {
        totalPeople: people.length,
        activePeople: activePeople,
        totalMeetings: totalMeetings,
        todayAttendance: todayAttendance,
        attendanceRate: attendanceRate,
        systemStatus: systemStatus
      }
    };
  } catch (err) {
    return { ok: false, code: 'ERROR', message: err.message };
  }
}

/**
 * جلب الإعدادات كـ object
 */
function getSettingsObject() {
  const rows = getSheetData('Settings');
  const obj = {};
  rows.forEach(r => {
    obj[r.Key] = r.Value;
  });
  return obj;
}

/**
 * جلب الإعدادات للـFrontend
 */
function getPublicSettings(email) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };

  const settings = getSettingsObject();
  return { ok: true, settings: settings };
}
```

### 4. عدّل دالة `doGet` في `Code.gs`

ابحث عن `switch (action)` وضيف الحالات الجديدة جوه:

```javascript
case 'dashboardStats':
  return jsonResponse(getDashboardStats(email));

case 'getSettings':
  return jsonResponse(getPublicSettings(email));
```

**مثال للشكل النهائي:**

```javascript
function doGet(e) {
  const action = e.parameter.action;
  const email = e.parameter.email;

  try {
    switch (action) {
      case 'ping':
        return jsonResponse({ ok: true, message: 'API is running' });

      case 'login':
        return jsonResponse(loginUser(email));

      case 'checkPermission':
        return jsonResponse({
          ok: true,
          hasPermission: hasPermission(email, e.parameter.role)
        });

      case 'dashboardStats':
        return jsonResponse(getDashboardStats(email));

      case 'getSettings':
        return jsonResponse(getPublicSettings(email));

      default:
        return jsonResponse({ ok: false, message: 'Unknown action' });
    }
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}
```

