```javascript
/**
 * جلب كل الإعدادات (Owner فقط)
 */
function getSettingsFull(email) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }
  return { ok: true, settings: getSettingsObject() };
}

/**
 * تحديث مجموعة إعدادات
 * settingsObj: { Key1: Value1, Key2: Value2 }
 */
function updateSettings(email, settingsObj) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  if (!settingsObj || typeof settingsObj !== 'object') {
    return { ok: false, code: 'BAD_INPUT', message: 'بيانات غير صحيحة' };
  }

  const sheet = getSheet('Settings');
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const keyCol = headers.indexOf('Key');
  const valueCol = headers.indexOf('Value');
  const updatedAtCol = headers.indexOf('UpdatedAt');

  const updated = [];

  for (let i = 1; i < data.length; i++) {
    const key = data[i][keyCol];
    if (Object.prototype.hasOwnProperty.call(settingsObj, key)) {
      sheet.getRange(i + 1, valueCol + 1).setValue(settingsObj[key]);
      if (updatedAtCol !== -1) {
        sheet.getRange(i + 1, updatedAtCol + 1).setValue(new Date());
      }
      updated.push(key);
    }
  }

  logAction(email, 'UPDATE_SETTINGS', 'Settings', '', 'تم تحديث: ' + updated.join(', '), 'Success');

  return { ok: true, updated: updated, settings: getSettingsObject() };
}

/**
 * رفع ملف (لوجو أو صورة خلفية) إلى Google Drive
 * fileData: { name, mimeType, base64 }
 */
function uploadFile(email, fileData) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  if (!fileData || !fileData.base64 || !fileData.mimeType) {
    return { ok: false, code: 'BAD_INPUT', message: 'بيانات الملف ناقصة' };
  }

  const folderName = 'AttendanceSystem_Assets';

  let folder;
  const folders = DriveApp.getFoldersByName(folderName);
  if (folders.hasNext()) {
    folder = folders.next();
  } else {
    folder = DriveApp.createFolder(folderName);
  }

  // فك التشفير
  const bytes = Utilities.base64Decode(fileData.base64);
  const blob = Utilities.newBlob(bytes, fileData.mimeType, fileData.name);

  const file = folder.createFile(blob);
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  const url = 'https://drive.google.com/uc?export=view&id=' + file.getId();

  logAction(email, 'UPLOAD_FILE', 'Drive', file.getId(), 'رفع: ' + fileData.name, 'Success');

  return { ok: true, url: url, fileId: file.getId() };
}
```

