```javascript
/**
 * الإعدادات — مع Cache
 */
function getSettingsObject() {
  const cache = CacheService.getScriptCache();
  const cacheKey = 'settings_v1';

  try {
    const cached = cache.get(cacheKey);
    if (cached) return JSON.parse(cached);
  } catch (e) {}

  const rows = getSheetData('Settings');
  const obj = {};
  rows.forEach(r => {
    obj[r.Key] = r.Value;
  });

  try {
    cache.put(cacheKey, JSON.stringify(obj), 300); // 5 دقايق
  } catch (e) {}

  return obj;
}

