/**
 * إحصائيات الـDashboard
 */
function getDashboardStats(email) {
  const auth = loginUser(email);
  if (!auth.ok) {
    return { ok: false, code: auth.code, message: auth.message };
  }

  const allowedRoles = ['Owner', 'Admin'];
  const hasAccess = auth.roles.some(r => allowedRoles.includes(r));
  if (!hasAccess) {
    return { ok: false, code: 'FORBIDDEN', message: 'ليس لديك صلاحية الوصول' };
  }

  try {
    const people = getSheetData('People');
    const meetings = getSheetData('Meetings');
    const attendance = getSheetData('Attendance');
    const settings = getSettingsObject();

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const activePeople = people.filter(p =>
      String(p.Status).toLowerCase() === 'active'
    ).length;

    const totalMeetings = meetings.filter(m =>
      String(m.Status).toLowerCase() !== 'archived'
    ).length;

    const todayAttendance = attendance.filter(a => {
      const scanDate = new Date(a.ScanTime);
      scanDate.setHours(0, 0, 0, 0);
      return scanDate.getTime() === today.getTime();
    }).length;

    const attendanceRate = activePeople > 0
      ? Math.round((todayAttendance / activePeople) * 100)
      : 0;

    return {
      ok: true,
      stats: {
        totalPeople: people.length,
        activePeople: activePeople,
        totalMeetings: totalMeetings,
        todayAttendance: todayAttendance,
        attendanceRate: attendanceRate,
        systemStatus: settings.SystemStatus || 'Active'
      }
    };
  } catch (err) {
    return { ok: false, code: 'ERROR', message: err.message };
  }
}

