## 1. Backend — ضيف دالة جديدة في `Dashboard.gs`

افتح `Dashboard.gs` → **ضيف الكود ده في آخر الملف** (مش محتاج تمسح حاجة):

```javascript
/**
 * استعادة إعدادات المظهر للقيم الافتراضية (Owner فقط)
 */
function resetThemeToDefault(email) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  const defaults = {
    ThemePrimary: '#475569',
    ThemeAccent: '#0d9488',
    ThemeBg: '#f8fafc',
    ThemeSidebarBg: '#1e293b',
    ThemeLogoUrl: '',
    ThemeBgImageUrl: ''
  };

  const sheet = getSheet('Settings');
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const keyCol = headers.indexOf('Key');
  const valueCol = headers.indexOf('Value');
  const updatedAtCol = headers.indexOf('UpdatedAt');

  const updated = [];

  for (let i = 1; i < data.length; i++) {
    const key = data[i][keyCol];
    if (Object.prototype.hasOwnProperty.call(defaults, key)) {
      sheet.getRange(i + 1, valueCol + 1).setValue(defaults[key]);
      if (updatedAtCol !== -1) {
        sheet.getRange(i + 1, updatedAtCol + 1).setValue(new Date());
      }
      updated.push(key);
    }
  }

  // امسح كاش الإعدادات
  clearSettingsCache();

  logAction(email, 'RESET_THEME', 'Settings', '', 'استعادة المظهر الافتراضي', 'Success');

  return { ok: true, updated: updated, settings: getSettingsObject() };
}
```

