      ['ThemeAccent', '#0d9488', 'لون التمييز', new Date()],
      ['ThemeBg', '#f8fafc', 'لون الخلفية', new Date()],
      ['ThemeSidebarBg', '#1e293b', 'لون الـSidebar', new Date()],
      ['ThemeLogoUrl', '', 'رابط اللوجو', new Date()],
      ['ThemeBgImageUrl', '', 'رابط صورة الخلفية', new Date()]
    ];

    settingsSheet
      .getRange(2, 1, defaults.length, defaults[0].length)
      .setValues(defaults);
  }

  SpreadsheetApp.getActive().toast('تم تجهيز قاعدة البيانات بنجاح');
}

function doGet(e) {
  const action = e.parameter.action;
  const email = e.parameter.email;

  try {
    switch (action) {
      case 'ping':
        return jsonResponse({ ok: true, message: 'API is running' });

      case 'login':
        return jsonResponse(loginUser(email));

      case 'checkPermission':
        return jsonResponse({
          ok: true,
          hasPermission: hasPermission(email, e.parameter.role)
        });

      case 'dashboardStats':
        return jsonResponse(getDashboardStats(email));

      case 'dashboardInit':
        return jsonResponse(getDashboardInit(email));

      case 'getSettings':
        return jsonResponse(getPublicSettings(email));

      case 'getSettingsFull':
        return jsonResponse(getSettingsFull(email));

      default:
        return jsonResponse({ ok: false, message: 'Unknown action' });
    }
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function doPost(e) {
  try {
    const body = JSON.parse(e.postData.contents);
    const action = body.action;
    const email = body.email;

    switch (action) {
      case 'login':
        return jsonResponse(loginUser(email));

      case 'updateSettings':
        return jsonResponse(updateSettings(email, body.settings));

      case 'uploadFile':
        return jsonResponse(uploadFile(email, body.file));

      case 'resetThemeToDefault':
        return jsonResponse(resetThemeToDefault(email));

      default:
        return jsonResponse({ ok: false, message: 'Unknown action' });
    }
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function jsonResponse(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(name);
  if (!sheet) throw new Error('Sheet not found: ' + name);
  return sheet;
}

function getSheetData(name) {
  const sheet = getSheet(name);
  const values = sheet.getDataRange().getValues();
  if (values.length < 2) return [];

  const headers = values[0];
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function appendRow(name, rowObj) {
  const sheet = getSheet(name);
  const headers = sheet
    .getRange(1, 1, 1, sheet.getLastColumn())
    .getValues()[0];

  const row = headers.map(h => rowObj[h] !== undefined ? rowObj[h] : '');
  sheet.appendRow(row);
  return rowObj;
}

function generateId(prefix) {
  return prefix + '-' + Utilities.getUuid().slice(0, 8);
}
