  });

  var boolKeys = ['PreventDuplicateAttendance','SuccessSound','ErrorSound',
                  'ShowPersonPhoto','AllowDelete','DisableInsteadOfDelete',
                  'CompressPhotos'];

  boolKeys.forEach(function(key) {
    var el = document.getElementById('set_' + key);
