### 1. `js/dashboard.js` — تحسين معالجة الأخطاء

**استبدل دالة `loadDashboardInit` بالكامل:**

```javascript
function loadDashboardInit(useCache) {
  var area = document.getElementById('contentArea');

  // 1) جرّب من الذاكرة
  if (useCache && dashInitCache) {
    applyDashboardData(dashInitCache);
    return;
  }

  // 2) جرّب من sessionStorage (مع حماية)
  if (useCache) {
    try {
      var saved = sessionStorage.getItem('dashInitCache');
      if (saved) {
        var parsed = JSON.parse(saved);
        if (parsed && parsed.data && parsed._ts && (Date.now() - parsed._ts) < 60000) {
          dashInitCache = parsed.data;
          applyDashboardData(dashInitCache);
          return;
        } else {
          // بيانات قديمة أو تالفة
          sessionStorage.removeItem('dashInitCache');
        }
      }
    } catch (e) {
      try { sessionStorage.removeItem('dashInitCache'); } catch (e2) {}
    }
  }

  // 3) Fetch من السيرفر مع Timeout + Retry
  area.innerHTML = '<div class="loading-state"><div class="spinner"></div><div>جاري التحميل...</div></div>';

  fetchWithTimeout(
    CONFIG.API_URL + '?action=dashboardInit&email=' + encodeURIComponent(dashboardUser.email),
    {},
    25000 // 25 ثانية
  )
    .then(function(res) {
      if (!res.ok) {
        throw new Error('HTTP ' + res.status);
      }
      return res.json();
    })
    .then(function(data) {
      if (!data) {
        throw new Error('رد فارغ من السيرفر');
      }
      if (!data.ok) {
        area.innerHTML =
          '<div class="placeholder-page">' +
            '<h2>خطأ</h2>' +
            '<p>' + (data.message || 'حدث خطأ غير متوقع') + '</p>' +
            '<p style="font-size:12px;color:#94a3b8;margin-top:8px;">الكود: ' + (data.code || 'UNKNOWN') + '</p>' +
            '<button class="btn-primary" onclick="loadDashboardInit(false)" style="margin-top:16px;">إعادة المحاولة</button>' +
          '</div>';
        return;
      }

      if (!data.stats || !data.settings) {
        throw new Error('البيانات ناقصة من السيرفر');
      }

      dashInitCache = data;
      try {
        sessionStorage.setItem('dashInitCache', JSON.stringify({
          data: data,
          _ts: Date.now()
        }));
      } catch (e) {}

      applyDashboardData(data);
    })
    .catch(function(err) {
      console.error('Dashboard error:', err);

      area.innerHTML =
        '<div class="placeholder-page">' +
          '<h2>خطأ في الاتصال</h2>' +
          '<p>' + (err.message || 'فشل الاتصال بالسيرفر') + '</p>' +
          '<p style="font-size:12px;color:#94a3b8;margin-top:8px;">قد يكون السيرفر بطيء أو الإنترنت ضعيف</p>' +
          '<button class="btn-primary" onclick="loadDashboardInit(false)" style="margin-top:16px;">إعادة المحاولة</button>' +
        '</div>';
    });
}

/**
 * ⚡ fetch مع Timeout
 */
function fetchWithTimeout(url, options, timeoutMs) {
  return new Promise(function(resolve, reject) {
    var controller = new AbortController();
    var timer = setTimeout(function() {
      controller.abort();
      reject(new Error('انتهت مدة الانتظار'));
    }, timeoutMs);

    fetch(url, Object.assign({}, options, { signal: controller.signal }))
      .then(function(res) {
        clearTimeout(timer);
        resolve(res);
      })
      .catch(function(err) {
        clearTimeout(timer);
        reject(err);
      });
  });
}
```

