**أو الأفضل:** شيل `keepAlive` خالص دلوقتي، لأن الـCache حل المشكلة.

### 4. `Dashboard.gs` — تحسين `getDashboardInit`

**ضيف `try-catch` في مكان أفضل:**

```javascript
function getDashboardInit(email) {
  try {
    // 1) Auth
    let auth;
    try {
      auth = loginUser(email);
    } catch (e) {
      return { ok: false, code: 'AUTH_ERROR', message: 'خطأ في التحقق: ' + e.message };
    }

    if (!auth.ok) {
      return { ok: false, code: auth.code, message: auth.message };
    }

    const allowedRoles = ['Owner', 'Admin'];
    const hasAccess = auth.roles.some(r => allowedRoles.includes(r));
    if (!hasAccess) {
      return { ok: false, code: 'FORBIDDEN', message: 'ليس لديك صلاحية الوصول' };
    }

    // 2) Cache
    const cache = CacheService.getScriptCache();
    const cacheKey = 'dashinit_v3';
    try {
      const cached = cache.get(cacheKey);
      if (cached) {
        const parsed = JSON.parse(cached);
        if (parsed && parsed.ok) return parsed;
      }
    } catch (e) {
      // cache error، كمّل
    }

    // 3) PropertiesService
    const props = PropertiesService.getScriptProperties();
    try {
      const stored = props.getProperty(cacheKey);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed && parsed.data && parsed._ts && (Date.now() - parsed._ts) < 300000) {
          try { cache.put(cacheKey, JSON.stringify(parsed.data), 60); } catch (e) {}
          return parsed.data;
        }
      }
    } catch (e) {
      // properties error، كمّل
    }

    // 4) اجلب من الشيتات
    let people, meetings, attendance, settings;
    try {
      people = getSheetData('People');
    } catch (e) {
      return { ok: false, code: 'SHEET_ERROR', message: 'خطأ في قراءة People: ' + e.message };
    }
    try {
      meetings = getSheetData('Meetings');
    } catch (e) {
      return { ok: false, code: 'SHEET_ERROR', message: 'خطأ في قراءة Meetings: ' + e.message };
    }
    try {
      attendance = getSheetData('Attendance');
    } catch (e) {
      return { ok: false, code: 'SHEET_ERROR', message: 'خطأ في قراءة Attendance: ' + e.message };
    }
    try {
      settings = getSettingsObject();
    } catch (e) {
      return { ok: false, code: 'SHEET_ERROR', message: 'خطأ في قراءة Settings: ' + e.message };
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const activePeople = people.filter(p =>
      String(p.Status).toLowerCase() === 'active'
    ).length;

    const totalMeetings = meetings.filter(m =>
      String(m.Status).toLowerCase() !== 'archived'
    ).length;

    const todayAttendance = attendance.filter(a => {
      if (!a.ScanTime) return false;
      const scanDate = new Date(a.ScanTime);
      if (isNaN(scanDate.getTime())) return false;
      scanDate.setHours(0, 0, 0, 0);
      return scanDate.getTime() === today.getTime();
    }).length;

    const attendanceRate = activePeople > 0
      ? Math.round((todayAttendance / activePeople) * 100)
      : 0;

    const result = {
      ok: true,
      stats: {
        totalPeople: people.length,
        activePeople: activePeople,
        totalMeetings: totalMeetings,
        todayAttendance: todayAttendance,
        attendanceRate: attendanceRate,
        systemStatus: settings.SystemStatus || 'Active'
      },
      settings: settings
    };

    try { cache.put(cacheKey, JSON.stringify(result), 60); } catch (e) {}
    try { props.setProperty(cacheKey, JSON.stringify({ data: result, _ts: Date.now() })); } catch (e) {}

    return result;

  } catch (err) {
    return {
      ok: false,
      code: 'FATAL',
      message: 'خطأ غير متوقع: ' + (err.message || 'unknown')
    };
  }
}
