/**
 * تحديث مجموعة إعدادات (Owner فقط)
 */
function updateSettings(email, settingsObj) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  if (!settingsObj || typeof settingsObj !== 'object') {
    return { ok: false, code: 'BAD_INPUT', message: 'بيانات غير صحيحة' };
  }

  const sheet = getSheet('Settings');
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const keyCol = headers.indexOf('Key');
  const valueCol = headers.indexOf('Value');
  const updatedAtCol = headers.indexOf('UpdatedAt');

  const updated = [];

  for (let i = 1; i < data.length; i++) {
    const key = data[i][keyCol];
    if (Object.prototype.hasOwnProperty.call(settingsObj, key)) {
      sheet.getRange(i + 1, valueCol + 1).setValue(normalizeSettingValue(settingsObj[key]));
      if (updatedAtCol !== -1) {
        sheet.getRange(i + 1, updatedAtCol + 1).setValue(new Date());
      }
      updated.push(key);
    }
  }

  // ✅ امسح الكاش (الإعدادات + الداشبورد) عشان القيم الجديدة تظهر فورًا
  clearSettingsCache();
  clearDashboardCache();

  logAction(email, 'UPDATE_SETTINGS', 'Settings', '', 'تم تحديث: ' + updated.join(', '), 'Success');

  return { ok: true, updated: updated, settings: getSettingsObject() };
}

/**
 * ⚡ تحويل القيم من الفورم للصيغة الصحيحة
 * "true" → true, "123" → 123, "" → ""
 */
function normalizeSettingValue(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value;

  const str = String(value).trim();

  if (str === 'true') return true;
  if (str === 'false') return false;

  if (str !== '' && !isNaN(str) && !isNaN(parseFloat(str))) {
    return Number(str);
  }

  return str;
}

