function uploadFile(email, fileData) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  if (!fileData || !fileData.base64 || !fileData.mimeType) {
    return { ok: false, code: 'BAD_INPUT', message: 'بيانات الملف ناقصة' };
  }

  const folderName = 'AttendanceSystem_Assets';

  let folder;
  const folders = DriveApp.getFoldersByName(folderName);
  if (folders.hasNext()) {
    folder = folders.next();
  } else {
    folder = DriveApp.createFolder(folderName);
  }

  const bytes = Utilities.base64Decode(fileData.base64);
  const blob = Utilities.newBlob(bytes, fileData.mimeType, fileData.name);

  const file = folder.createFile(blob);
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  const url = 'https://lh3.googleusercontent.com/d/' + file.getId();

  logAction(email, 'UPLOAD_FILE', 'Drive', file.getId(), 'رفع: ' + fileData.name, 'Success');

  return { ok: true, url: url, fileId: file.getId() };
}

