## التعديل في `Dashboard.gs`

افتح `Dashboard.gs` → **استبدل دالة `uploadFile` بالكامل** بالكود ده:

```javascript
/**
 * رفع ملف (لوجو أو خلفية) — Owner فقط
 * ⚡ يستبدل الملف لو موجود بنفس الاسم بدل إنشاء نسخة جديدة
 */
function uploadFile(email, fileData) {
  const auth = loginUser(email);
  if (!auth.ok) return { ok: false, code: auth.code, message: auth.message };
  if (!auth.roles.includes('Owner')) {
    return { ok: false, code: 'FORBIDDEN', message: 'Owner فقط' };
  }

  if (!fileData || !fileData.base64 || !fileData.mimeType) {
    return { ok: false, code: 'BAD_INPUT', message: 'بيانات الملف ناقصة' };
  }

  const folderName = 'AttendanceSystem_Assets';

  let folder;
  const folders = DriveApp.getFoldersByName(folderName);
  if (folders.hasNext()) {
    folder = folders.next();
  } else {
    folder = DriveApp.createFolder(folderName);
  }

  // ⚡ دوّر على ملف بنفس الاسم
  const fileName = fileData.name;
  const existingFiles = folder.getFilesByName(fileName);

  let file;
  let isNew = false;

  if (existingFiles.hasNext()) {
    // موجود → استبدل المحتوى
    file = existingFiles.next();
    const bytes = Utilities.base64Decode(fileData.base64);
    const blob = Utilities.newBlob(bytes, fileData.mimeType, fileName);
    file.setContent(blob.getDataAsString());
    file.setTrashed(false);
  } else {
    // مش موجود → اعمل جديد
    const bytes = Utilities.base64Decode(fileData.base64);
    const blob = Utilities.newBlob(bytes, fileData.mimeType, fileName);
    file = folder.createFile(blob);
    isNew = true;
  }

  // تأكد من الصلاحيات
  try {
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
  } catch (e) {}

  // رابط العرض السريع
  const url = 'https://lh3.googleusercontent.com/d/' + file.getId();

  logAction(
    email,
    isNew ? 'UPLOAD_FILE' : 'REPLACE_FILE',
    'Drive',
    file.getId(),
    (isNew ? 'رفع: ' : 'استبدال: ') + fileName,
    'Success'
  );

  return { ok: true, url: url, fileId: file.getId(), replaced: !isNew };
}
```

**احفظ + Deploy → New version → Deploy.**

