## الجزء 3: Frontend

### عدّل `js/settings.js`

افتح `js/settings.js` → **دوّر على دالة `uploadImage`** واستبدلها بالكامل:

```javascript
function uploadImage(file, settingKey, previewId) {
  if (file.size > 2 * 1024 * 1024) {
    alert('حجم الصورة كبير جدًا. الحد الأقصى 2MB');
    return;
  }

  var reader = new FileReader();
  reader.onload = function(e) {
    var base64 = e.target.result.split(',')[1];

    fetch(CONFIG.API_URL, {
      method: 'POST',
      body: JSON.stringify({
        action: 'uploadFile',
        email: dashboardUser.email,
        file: {
          name: file.name,
          mimeType: file.type,
          base64: base64
        }
      })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (!data.ok) {
        alert('خطأ: ' + data.message);
        return;
      }

      // ⚡ امسح الملف القديم لو موجود
      var oldFileIdKey = settingKey === 'ThemeLogoUrl' ? 'ThemeLogoFileId' : 'ThemeBgImageFileId';
      var oldFileId = settingsData[oldFileIdKey];

      if (oldFileId && oldFileId !== data.fileId) {
        deleteFileOnDrive(oldFileId);
      }

      // احفظ الـURL والـfileId الجديد
      settingsData[settingKey] = data.url;
      settingsData[oldFileIdKey] = data.fileId;

      var preview = document.getElementById(previewId);
      if (preview) {
        preview.src = data.url;
        preview.style.display = 'block';
      }
    })
    .catch(function(err) {
      alert('خطأ في الرفع: ' + err.message);
    });
  };
  reader.readAsDataURL(file);
}

/**
 * ⚡ حذف ملف من Google Drive
 */
function deleteFileOnDrive(fileId) {
  if (!fileId) return;

  fetch(CONFIG.API_URL, {
    method: 'POST',
    body: JSON.stringify({
      action: 'deleteFile',
      email: dashboardUser.email,
      fileId: fileId
    })
  })
  .then(function(res) { return res.json(); })
  .then(function(data) {
    if (data.ok) {
      console.log('تم حذف الملف القديم:', fileId);
    } else {
      console.warn('فشل حذف الملف:', data.message);
    }
  })
  .catch(function(err) {
    console.warn('خطأ في حذف الملف:', err);
  });
}
```

### عدّل `clearLogo` و `clearBgImage`

استبدلهم بالكود ده:

```javascript
function clearLogo() {
  if (!confirm('هل أنت متأكد من مسح اللوجو؟ سيتم حذفه من Google Drive أيضًا.')) {
    return;
  }

  var oldFileId = settingsData.ThemeLogoFileId;
  if (oldFileId) {
    deleteFileOnDrive(oldFileId);
  }

  settingsData.ThemeLogoUrl = '';
  settingsData.ThemeLogoFileId = '';

  var preview = document.getElementById('logoPreview');
  if (preview) {
    preview.src = '';
    preview.style.display = 'none';
  }

  // ⚡ امسحهم من الشيت فورًا
  saveFieldsImmediately({
    ThemeLogoUrl: '',
    ThemeLogoFileId: ''
  });
}

function clearBgImage() {
  if (!confirm('هل أنت متأكد من مسح الخلفية؟ سيتم حذفها من Google Drive أيضًا.')) {
    return;
  }

  var oldFileId = settingsData.ThemeBgImageFileId;
  if (oldFileId) {
    deleteFileOnDrive(oldFileId);
  }

  settingsData.ThemeBgImageUrl = '';
  settingsData.ThemeBgImageFileId = '';

  var preview = document.getElementById('bgPreview');
  if (preview) {
    preview.src = '';
    preview.style.display = 'none';
  }

  saveFieldsImmediately({
    ThemeBgImageUrl: '',
    ThemeBgImageFileId: ''
  });
}

/**
 * ⚡ حفظ فوري لحقول معينة (للمسح)
 */
function saveFieldsImmediately(fields) {
  fetch(CONFIG.API_URL, {
    method: 'POST',
    body: JSON.stringify({
      action: 'updateSettings',
      email: dashboardUser.email,
      settings: fields
    })
  })
  .then(function(res) { return res.json(); })
  .then(function(data) {
    if (data.ok) {
      settingsData = data.settings;
      dashInitCache = null;
      try { sessionStorage.removeItem('dashInitCache'); } catch (e) {}
    }
  })
  .catch(function(err) {
    console.warn('فشل الحفظ الفوري:', err);
  });
}
```

### عدّل `saveAllSettings` عشان تبعت `fileId` كمان

في `saveAllSettings`، غيّر السطرين دول:

**قبل:**
```javascript
payload.ThemeLogoUrl = settingsData.ThemeLogoUrl || '';
payload.ThemeBgImageUrl = settingsData.ThemeBgImageUrl || '';
```

**بعد:**
```javascript
payload.ThemeLogoUrl = settingsData.ThemeLogoUrl || '';
payload.ThemeBgImageUrl = settingsData.ThemeBgImageUrl || '';
payload.ThemeLogoFileId = settingsData.ThemeLogoFileId || '';
payload.ThemeBgImageFileId = settingsData.ThemeBgImageFileId || '';
```

### عدّل `fillSettingsForm` عشان تحمّل `fileId`

في `fillSettingsForm`، **مش محتاج تعرضهم**، بس نتأكد إنهم محمّلين في `settingsData`. `settingsData` بتاخد كل الإعدادات من `getSettingsFull`، فمفيش حاجة تتضاف.

**بس تأكد** إن `settingsData` فيها `ThemeLogoFileId` و `ThemeBgImageFileId` بعد `getSettingsFull`.

