### الخطوة 2: إعداد Firestore Rules

**افتح:**
```
https://console.firebase.google.com/project/attendance-system-2dc6f/firestore/rules
```

**هتلاقي محرر فيه Rules حالية.**

**امسح كل حاجة** والصق ده:

```
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    function isSignedIn() {
      return request.auth != null;
    }

    function userRole() {
      return get(/databases/$(database)/documents/accounts/$(request.auth.uid)).data.Role;
    }

    function isOwner() {
      return isSignedIn() && userRole() == 'Owner';
    }

    function isAdmin() {
      return isSignedIn() && (userRole() == 'Admin' || userRole() == 'Owner');
    }

    function isScanner() {
      return isSignedIn() && (userRole() == 'Scanner' || userRole() == 'Admin' || userRole() == 'Owner');
    }

    match /accounts/{accountId} {
      allow read: if isSignedIn();
      allow write: if isOwner();
    }

    match /people/{personId} {
      allow read: if isSignedIn();
      allow write: if isAdmin();
    }

    match /meetings/{meetingId} {
      allow read: if isSignedIn();
      allow write: if isAdmin();
    }

    match /attendance/{attendanceId} {
      allow read: if isSignedIn();
      allow create: if isScanner();
      allow update, delete: if isAdmin();
    }

    match /settings/{settingId} {
      allow read: if isSignedIn();
      allow write: if isOwner();
    }

    match /logs/{logId} {
      allow read: if isAdmin();
      allow create: if isSignedIn();
      allow update, delete: if false;
    }

    match /archivedMeetings/{id} {
      allow read: if isAdmin();
      allow write: if isAdmin();
    }

    match /archivedAttendance/{id} {
      allow read: if isAdmin();
      allow write: if isAdmin();
    }
  }
}
```

