async function loadSettingsPage(area) {
  area.innerHTML = '<div class="loading-state"><div class="spinner"></div><div>جاري التحميل...</div></div>';

  try {
    const settingsRef = doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC);
