      avatar.innerHTML = `<img src="${dashboardUser.photoURL}" alt="" style="width:100%;height:100%;border-radius:50%;object-fit:cover;">`;
    } else if (dashboardUser.name) {
      avatar.textContent = dashboardUser.name.charAt(0).toUpperCase();
    }
