        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon">✅</div>
        <div class="stat-info">
          <div class="stat-label">الأشخاص النشطين</div>
          <div class="stat-value">${stats.activePeople}</div>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon">📅</div>
        <div class="stat-info">
          <div class="stat-label">إجمالي الاجتماعات</div>
          <div class="stat-value">${stats.totalMeetings}</div>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon">📌</div>
        <div class="stat-info">
