// ═══ Location Detection ═══
window.detectMyLocation = function() {
  if (!navigator.geolocation) {
    alert('المتصفح لا يدعم خدمة الموقع');
    return;
  }

  const btn = event.target;
  const originalText = btn.textContent;
  btn.disabled = true;
  btn.textContent = '⏳ جاري تحديد الموقع...';

  navigator.geolocation.getCurrentPosition(
    (pos) => {
      const lat = pos.coords.latitude;
      const lng = pos.coords.longitude;
      const accuracy = pos.coords.accuracy;

      document.getElementById('set_LocationLatitude').value = lat.toFixed(6);
      document.getElementById('set_LocationLongitude').value = lng.toFixed(6);

      btn.disabled = false;
      btn.textContent = originalText;

      alert(`✅ تم تحديد الموقع:\n\nLatitude: ${lat.toFixed(6)}\nLongitude: ${lng.toFixed(6)}\n\nدقة القياس: ${Math.round(accuracy)} متر`);
    },
    (err) => {
      btn.disabled = false;
      btn.textContent = originalText;
      alert('❌ فشل تحديد الموقع: ' + err.message);
    },
    { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
  );
};

window.previewLocationMap = function() {
  const lat = parseFloat(document.getElementById('set_LocationLatitude')?.value);
  const lng = parseFloat(document.getElementById('set_LocationLongitude')?.value);

  if (isNaN(lat) || isNaN(lng)) {
    alert('حدد الموقع أولاً');
    return;
  }

  const url = `https://www.google.com/maps?q=${lat},${lng}`;
  window.open(url, '_blank');
};

// ═══ System QR ═══
function generateSystemQRCode() {
  // توليد رمز فريد للنظام
  const projectId = 'attendance-system-2dc6f';
  const randomPart = Math.random().toString(36).substring(2, 10);
  const timestamp = Date.now().toString(36);
  return `ATTENDANCE_SYS_${projectId}_${randomPart}${timestamp}`;
}

async function renderSystemQR() {
  const container = document.getElementById('qrSystemContainer');
  if (!container) return;

  let qrCode = settingsData.SystemQRCode;

  // لو مش موجود، ولّد واحد جديد
  if (!qrCode) {
    qrCode = generateSystemQRCode();
    settingsData.SystemQRCode = qrCode;
    // احفظه فورًا
    try {
      await setDoc(doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC),
        { SystemQRCode: qrCode }, { merge: true });
    } catch (e) {
      console.error('Save QR error:', e);
    }
  }

  // اعرض الـQR
  container.innerHTML = '<div id="qrSystemCanvas" class="qr-system-canvas"></div>';

  if (typeof QRCode !== 'undefined') {
    new QRCode(document.getElementById('qrSystemCanvas'), {
      text: qrCode,
      width: 220,
      height: 220,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.H
    });
  } else {
    container.innerHTML = `
      <div style="text-align:center;padding:20px;">
        <p style="color:#64748b;">مكتبة QR غير محمّلة</p>
        <code style="display:block;padding:10px;background:#f1f5f9;border-radius:8px;font-size:12px;word-break:break-all;margin-top:8px;">${qrCode}</code>
      </div>
    `;
  }
}

window.copyQRCode = function() {
  const code = settingsData.SystemQRCode;
  if (!code) return;

  navigator.clipboard.writeText(code).then(() => {
    alert('✅ تم نسخ الرمز');
  }).catch(() => {
    alert('الرمز:\n\n' + code);
  });
};

window.printSystemQR = function() {
  const container = document.getElementById('qrSystemContainer');
  if (!container) return;

  const printWindow = window.open('', '_blank');
  printWindow.document.write(`
    <html dir="rtl">
      <head>
        <title>QR الحضور</title>
        <style>
          body { font-family: Arial; text-align: center; padding: 60px; }
          h1 { font-size: 28px; margin-bottom: 10px; }
          h2 { font-size: 20px; color: #666; margin-bottom: 40px; }
          .qr-box { display: inline-block; padding: 30px; border: 3px solid #000; border-radius: 16px; }
          .hint { margin-top: 40px; font-size: 16px; color: #333; }
        </style>
      </head>
      <body>
        <h1>${settingsData.SystemName || 'سجل حضورك'}</h1>
        <h2>امسح الـQR لتسجيل حضورك</h2>
        <div class="qr-box">${container.innerHTML}</div>
        <p class="hint">اتبع التعليمات على الشاشة</p>
      </body>
    </html>
  `);
  printWindow.document.close();
  setTimeout(() => printWindow.print(), 500);
};

window.regenerateQR = async function() {
  if (!confirm('⚠️ تحذير: توليد QR جديد سيُلغي القديم.\n\nالأفراد اللي عندهم QR قديم مش هيقدروا يسجلوا.\n\nهل أنت متأكد؟')) {
    return;
  }

  const newCode = generateSystemQRCode();
  settingsData.SystemQRCode = newCode;

  try {
    await setDoc(doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC),
      { SystemQRCode: newCode }, { merge: true });

    renderSystemQR();
    alert('✅ تم توليد QR جديد');
  } catch (e) {
    console.error('Regenerate QR error:', e);
    alert('خطأ: ' + e.message);
  }
};

// ═══ Save Settings ═══
window.saveAllSettings = async function(event) {
  const textKeys = ['SystemName','OrganizationName','Language','TimeZone',
                    'ThemePrimary','ThemeAccent','ThemeBg','ThemeSidebarBg',
                    'OpenBeforeMinutes','CloseAfterMinutes','ResultDisplayDuration',
                    'RequiredFields','MaxPhotoSize','ThemeLogoUrl','ThemeBgImageUrl',
                    'LocationName','LocationLatitude','LocationLongitude',
                    'LocationRadius','LocationAccuracyTolerance'];

  const boolKeys = ['PreventDuplicateAttendance','SuccessSound','ErrorSound',
                    'ShowPersonPhoto','AllowDelete','DisableInsteadOfDelete',
                    'CompressPhotos','LocationEnabled'];

  const payload = {};

  textKeys.forEach(key => {
    const el = document.getElementById('set_' + key);
    if (el) payload[key] = el.value;
  });

  boolKeys.forEach(key => {
    const el = document.getElementById('set_' + key);
    if (el) payload[key] = el.checked;
  });

  // احتفظ بالـQR
  if (settingsData.SystemQRCode) {
    payload.SystemQRCode = settingsData.SystemQRCode;
  }

  const btn = event ? event.target : null;
  const originalText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'جاري الحفظ...'; }

  try {
    const settingsRef = doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC);
    await setDoc(settingsRef, payload, { merge: true });

    settingsData = { ...settingsData, ...payload };
    originalSettings = { ...settingsData };

    if (window.dashInitCache !== undefined) window.dashInitCache = null;
    try { sessionStorage.removeItem('dashInitCache'); } catch (e) {}

    const theme = extractTheme(settingsData);
    saveTheme(theme);

    const appNameEl = document.getElementById('appName');
    if (appNameEl && settingsData.SystemName) {
      appNameEl.textContent = settingsData.SystemName;
      document.title = settingsData.SystemName;
    }

    alert('تم الحفظ بنجاح');
  } catch (err) {
    console.error('❌ Save settings error:', err);
    alert('خطأ: ' + err.message);
  }

  if (btn) { btn.disabled = false; btn.textContent = originalText; }
};

// ═══ Reset Theme ═══
window.resetThemeToDefault = async function() {
  if (!confirm('هل أنت متأكد من استعادة المظهر الافتراضي؟')) return;

  const defaults = {
    ThemePrimary: DEFAULT_THEME.primary,
    ThemeAccent: DEFAULT_THEME.accent,
    ThemeBg: DEFAULT_THEME.bg,
    ThemeSidebarBg: DEFAULT_THEME.sidebarBg,
    ThemeLogoUrl: '',
    ThemeBgImageUrl: ''
  };

  try {
    const settingsRef = doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC);
    await setDoc(settingsRef, defaults, { merge: true });

    settingsData = { ...settingsData, ...defaults };
    saveTheme(DEFAULT_THEME);

    const area = document.getElementById('contentArea');
    if (area) loadSettingsPage(area);

    alert('تم استعادة المظهر الافتراضي');
  } catch (err) {
    console.error('❌ Reset theme error:', err);
    alert('خطأ: ' + err.message);
  }
};

// ═══ Reload ═══
window.reloadSettings = function() {
  const area = document.getElementById('contentArea');
  if (area) loadSettingsPage(area);
};

// ═══ Theme Helpers ═══
function extractTheme(s) {
  return {
    primary: s.ThemePrimary || DEFAULT_THEME.primary,
    primaryHover: DEFAULT_THEME.primaryHover,
    accent: s.ThemeAccent || DEFAULT_THEME.accent,
    bg: s.ThemeBg || DEFAULT_THEME.bg,
    cardBg: DEFAULT_THEME.cardBg,
    text: DEFAULT_THEME.text,
    textMuted: DEFAULT_THEME.textMuted,
    border: DEFAULT_THEME.border,
    sidebarBg: s.ThemeSidebarBg || DEFAULT_THEME.sidebarBg,
    sidebarText: DEFAULT_THEME.sidebarText,
    sidebarActive: DEFAULT_THEME.sidebarActive,
    logoUrl: s.ThemeLogoUrl || '',
    bgImageUrl: s.ThemeBgImageUrl || ''
  };
}

function saveTheme(theme) {
  localStorage.setItem('themeSettings', JSON.stringify(theme));

  const root = document.documentElement;
  const t = { ...DEFAULT_THEME, ...theme };

  root.style.setProperty('--primary', t.primary);
  root.style.setProperty('--primary-hover', t.primaryHover);
  root.style.setProperty('--accent', t.accent);
  root.style.setProperty('--bg', t.bg);
  root.style.setProperty('--card-bg', t.cardBg);
  root.style.setProperty('--text', t.text);
  root.style.setProperty('--text-muted', t.textMuted);
  root.style.setProperty('--border', t.border);
  root.style.setProperty('--sidebar-bg', t.sidebarBg);
  root.style.setProperty('--sidebar-text', t.sidebarText);
  root.style.setProperty('--sidebar-active', t.sidebarActive);

  if (t.bgImageUrl) {
    document.body.style.backgroundImage = `url('${t.bgImageUrl}')`;
    document.body.style.backgroundSize = 'cover';
    document.body.style.backgroundAttachment = 'fixed';
  } else {
    document.body.style.backgroundImage = 'none';
    document.body.style.background = t.bg;
  }

  document.querySelectorAll('.app-logo').forEach(img => {
    if (t.logoUrl) {
      img.src = t.logoUrl;
      img.style.display = 'block';
    } else {
      img.style.display = 'none';
    }
  });
}

// ═══ Expose ═══
window.loadSettingsPage = loadSettingsPage;
