## 📄 التعديلات

### 1. تعديل `js/people.js`

**هنضيف دالة `formatFacebookUrl` + نعدّل عرض Facebook في الـModal.**

**افتح `js/people.js` → ✏️ Edit**

**دوّر على الدالة `formatDateTime`:**

```javascript
function formatDateTime(date) {
  if (!date) return '';
  try {
    const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    const h = String(date.getHours()).padStart(2, '0');
    const m = String(date.getMinutes()).padStart(2, '0');
    return `${date.getDate()} ${months[date.getMonth()]} ${date.getFullYear()} - ${h}:${m}`;
  } catch (e) {
    return '';
  }
}
```

**ضيف بعدها دالة جديدة:**

```javascript
function formatFacebookUrl(value) {
  if (!value) return '';
  let url = String(value).trim();

  // لو رابط كامل
  if (url.startsWith('http://') || url.startsWith('https://')) {
    return url;
  }

  // لو رابط بدون بروتوكول
  if (url.startsWith('facebook.com') || url.startsWith('www.facebook.com') || url.startsWith('fb.com') || url.startsWith('m.facebook.com')) {
    return 'https://' + url;
  }

  // لو اسم مستخدم فقط
  url = url.replace(/^@/, ''); // شيل @ لو موجودة
  return 'https://facebook.com/' + url;
}

function getFacebookDisplay(value) {
  if (!value) return '-';
  let url = String(value).trim();

  // شيل البروتوكول
  url = url.replace(/^https?:\/\//, '');
  url = url.replace(/^www\./, '');
  url = url.replace(/^m\./, '');

  return url;
}
```

