## ✅ الحل: تحسين دالة `logout`

**افتح `js/dashboard.js` → ✏️ Edit**

**دوّر على:**

```javascript
// ═══ Logout ═══
window.logout = async function() {
  try {
    localStorage.removeItem('currentUser');
    try { sessionStorage.clear(); } catch (e) {}
    await signOut(auth);
  } catch (err) {
    console.error('Logout error:', err);
  }
  window.location.href = '../index.html';
};
```

**استبدلها بـ:**

```javascript
// ═══ Logout ═══
async function handleLogout() {
  // ⚡ أول حاجة: امسح الحالة المحلية وروح فورًا
  try {
    localStorage.removeItem('currentUser');
  } catch (e) {}

  try {
    sessionStorage.clear();
  } catch (e) {}

  // ⚡ روح لصفحة الدخول فورًا
  window.location.href = '../index.html';

  // ⚡ بعدها جرّب signOut من Firebase (مش هيأثر على الانتقال)
  try {
    await signOut(auth);
  } catch (err) {
    console.warn('SignOut error (non-blocking):', err);
  }
}

window.logout = handleLogout;

// ⚡ كمان اربط الزرار مباشرة لو موجود
document.addEventListener('DOMContentLoaded', () => {
  const logoutBtn = document.querySelector('.logout-btn');
  if (logoutBtn && !logoutBtn._bound) {
    logoutBtn._bound = true;
    logoutBtn.addEventListener('click', (e) => {
      e.preventDefault();
      handleLogout();
    });
  }
});
```

**Commit changes** → `fix: logout on mobile`

