// ═══ Ensure Person Link (ربط User بـPersonID) ═══
async function ensurePersonLink(firebaseUser, account) {
  // 1. لو account.PersonID موجود → استخدمه
  if (account.PersonID) {
    // تأكد إنه موجود في people
    try {
      const pDoc = await getDoc(doc(db, COLLECTIONS.PEOPLE, account.PersonID));
      if (pDoc.exists()) return account.PersonID;
    } catch (e) {}
  }

  // 2. دوّر بالبريد
  if (firebaseUser.email) {
    try {
      const { collection, query, where, getDocs } = await import(
        "https://www.gstatic.com/firebasejs/10.13.0/firebase-firestore.js"
      );

      const q = query(
        collection(db, COLLECTIONS.PEOPLE),
        where('Email', '==', firebaseUser.email)
      );
      const snap = await getDocs(q);

      if (!snap.empty) {
        const personDoc = snap.docs[0];
        return personDoc.id;
      }
    } catch (e) {
      console.warn('Person link error:', e);
    }
  }

  return null;
}
