  ].filter(Boolean).join(' ');

  // ⚡ لو مفيش اجتماعات
  if (maMeetings.length === 0) {
    container.innerHTML = `
      <div class="ma-empty">
        <div class="ma-empty-icon">📅</div>
        <h2>لا يوجد اجتماعات نشطة</h2>
        <p>سيظهر هنا الاجتماعات فور إضافتها.</p>
      </div>
    `;
