  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.att-badge.self {
  background: #dbeafe;
  color: #1e40af;
}

.att-badge.scanner {
  background: #dcfce7;
  color: #166534;
}

/* Pagination */
.att-pagination {
  display: flex;
  gap: 6px;
  justify-content: center;
  margin-top: 20px;
  flex-wrap: wrap;
}

.att-page-btn {
  padding: 8px 14px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  color: var(--text);
  transition: all 0.2s;
  min-width: 40px;
}

.att-page-btn:hover:not(:disabled) {
  border-color: var(--primary);
  color: var(--primary);
}

.att-page-btn.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.att-page-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Empty */
.att-empty {
  text-align: center;
  padding: 60px 20px;
  background: var(--card-bg);
  border: 1px dashed var(--border);
  border-radius: 14px;
}

.att-empty-icon {
  font-size: 60px;
  margin-bottom: 12px;
}

.att-empty h3 {
  color: var(--text);
  margin-bottom: 8px;
  font-size: 18px;
}

.att-empty p {
  color: var(--text-muted);
  font-size: 14px;
}

/* Responsive */
@media (max-width: 768px) {
  .att-header {
    flex-direction: column;
    align-items: stretch;
  }

  .att-header .btn-secondary {
    width: 100%;
  }

  .att-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .att-filters {
    grid-template-columns: 1fr;
    gap: 10px;
    padding: 14px;
  }

  .att-table {
    font-size: 12px;
  }

  .att-table th,
  .att-table td {
    padding: 9px 8px;
  }

  /* إخفاء أعمدة على الموبايل */
  .att-table th:nth-child(6),
  .att-table td:nth-child(6),
  .att-table th:nth-child(7),
  .att-table td:nth-child(7) {
    display: none;
  }

  .att-avatar,
  .att-avatar-placeholder {
    width: 30px;
    height: 30px;
    font-size: 12px;
  }

  .att-pagination {
    gap: 4px;
  }

  .att-page-btn {
    padding: 7px 10px;
    font-size: 12px;
    min-width: 34px;
  }
}

@media (max-width: 480px) {
  .att-stat-value {
    font-size: 18px;
  }

  .att-table {
    font-size: 11px;
  }
}
