  DEFAULT_THEME
} from './firebase-config.js';

// ═══ Menu Configuration ═══
const MENU_ITEMS = [
  { id: 'dashboard',      label: 'لوحة التحكم',          icon: '🏠', roles: ['Owner','Admin','Scanner','User'] },
  { id: 'profile',        label: 'حسابي',                 icon: '👤', roles: ['Owner','Admin','Scanner','User'] },
