// ═══ Navigation ═══
function navigateTo(pageId) {
  currentPage = pageId;

  document.querySelectorAll('.nav-item').forEach(b => {
    b.classList.toggle('active', b.dataset.page === pageId);
  });

  const item = MENU_ITEMS.find(m => m.id === pageId);
