## 📋 الخطوة 5: كود Apps Script

**من محرر Apps Script → ملف `Code.gs` → Ctrl+A → Delete → الصق ده:**

```javascript
// ═══════════════════════════════════════════════════════
//   Sync Google Form Responses → Firestore
// ═══════════════════════════════════════════════════════

const SHEET_ID = '1Ak-5RLNfmAFawOsoFdB-YEee6TSQi6XFOGpVWn6hxcE';
const SHEET_NAME = 'Form Responses 1';
const FIRESTORE_COLLECTION = 'people';
const SYNC_STATUS_COLUMN = 'SyncedAt'; // عمود إضافي لتتبع المزامنة

// ═══════════════════════════════════════════════════════
//   Firebase Admin SDK Init
// ═══════════════════════════════════════════════════════

function initFirebase() {
  const props = PropertiesService.getScriptProperties();

  const projectId = props.getProperty('FIREBASE_PROJECT_ID');
  const clientEmail = props.getProperty('FIREBASE_CLIENT_EMAIL');
  let privateKey = props.getProperty('FIREBASE_PRIVATE_KEY');

  if (!projectId || !clientEmail || !privateKey) {
    throw new Error('Firebase credentials not found in Script Properties');
  }

  // ⚡ عالج الـ newlines في private_key
  privateKey = privateKey.replace(/\\n/g, '\n');

  return FirebaseApp.getDatabaseByUrl(
    `https://${projectId}.firebaseio.com`,
    JSON.stringify({
      project_id: projectId,
      client_email: clientEmail,
      private_key: privateKey
    })
  );
}

// ═══════════════════════════════════════════════════════
//   Sync Function
// ═══════════════════════════════════════════════════════

function syncFormResponses() {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  const sheet = ss.getSheetByName(SHEET_NAME);

  if (!sheet) {
    throw new Error(`Sheet "${SHEET_NAME}" not found`);
  }

  const data = sheet.getDataRange().getValues();
  if (data.length < 2) {
    Logger.log('لا توجد بيانات للمزامنة');
    return { ok: true, added: 0, updated: 0, skipped: 0 };
  }

  const headers = data[0];
  const rows = data.slice(1);

  // ⚡ تأكد من وجود عمود SyncedAt
  let syncColIndex = headers.indexOf(SYNC_STATUS_COLUMN);
  if (syncColIndex === -1) {
    syncColIndex = headers.length;
    sheet.getRange(1, syncColIndex + 1).setValue(SYNC_STATUS_COLUMN);
    headers.push(SYNC_STATUS_COLUMN);
  }

  const fb = initFirebase();
  const ref = fb.getData('/' + FIRESTORE_COLLECTION);

  let added = 0;
  let updated = 0;
  let skipped = 0;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowNumber = i + 2;

    // تخطى لو متزامن قبل كده
    const syncedAt = row[syncColIndex];
    if (syncedAt) {
      skipped++;
      continue;
    }

    try {
      const personData = mapRowToPerson(headers, row);

      // ⚡ ابحث بالبريد في Firestore
      const existing = findPersonByEmail(ref, personData.Email);

      if (existing) {
        // حدّث
        ref.child(existing.id).update(personData);
        updated++;
        Logger.log(`Updated: ${personData.Email}`);
      } else {
        // أضف جديد
        const newRef = ref.push(personData);
        added++;
        Logger.log(`Added: ${personData.Email}`);
      }

      // ⚡ سجّل وقت المزامنة
      sheet.getRange(rowNumber, syncColIndex + 1).setValue(new Date());

    } catch (err) {
      Logger.log(`❌ Row ${rowNumber}: ${err.message}`);
    }
  }

  Logger.log(`✅ Done: Added=${added}, Updated=${updated}, Skipped=${skipped}`);
  return { ok: true, added, updated, skipped };
}

// ═══════════════════════════════════════════════════════
//   Map Row → Person Object
// ═══════════════════════════════════════════════════════

function mapRowToPerson(headers, row) {
  const get = (name) => {
    const idx = headers.indexOf(name);
    return idx !== -1 ? String(row[idx] || '').trim() : '';
  };

  return {
    FirstName: get('الاسم الأول'),
    SecondName: get('الاسم الثاني'),
    ThirdName: get('الاسم الثالث'),
    FourthName: get('الاسم الرابع'),
    BirthDate: formatDate(get('تاريخ الميلاد')),
    Gender: mapGender(get('النوع')),
    Address: get('العنوان'),
    Mobile: normalizePhone(get('رقم الموبايل')),
    WhatsApp: normalizePhone(get('رقم واتساب')),
    Email: get('البريد الإلكتروني').toLowerCase(),
    Facebook: get('رابط صفحة الفيسبوك (اختياري)'),
    PhotoURL: get('رابط صورتك الشخصية (اختياري)'),
    Status: 'active',
    QRCode: '',
    CreatedAt: new Date().toISOString(),
    Source: 'google_form'
  };
}

function mapGender(v) {
  if (!v) return '';
  if (v === 'ذكر') return 'male';
  if (v === 'أنثى') return 'female';
  return String(v).toLowerCase();
}

function normalizePhone(v) {
  if (!v) return '';
  return String(v).replace(/\s+/g, '').replace(/[^\d+]/g, '');
}

function formatDate(v) {
  if (!v) return '';
  try {
    if (v instanceof Date) {
      return Utilities.formatDate(v, 'Africa/Cairo', 'yyyy-MM-dd');
    }
    const d = new Date(v);
    if (isNaN(d.getTime())) return String(v);
    return Utilities.formatDate(d, 'Africa/Cairo', 'yyyy-MM-dd');
  } catch (e) {
    return String(v);
  }
}

// ═══════════════════════════════════════════════════════
//   Find Person by Email in Firestore
// ═══════════════════════════════════════════════════════

function findPersonByEmail(ref, email) {
  if (!email) return null;

  const all = ref.getData() || {};
  const list = Object.entries(all).map(([id, data]) => ({ id, ...data }));

  return list.find(p =>
    String(p.Email || '').toLowerCase() === email.toLowerCase()
  ) || null;
}

// ═══════════════════════════════════════════════════════
//   Setup Trigger (يعمل كل ساعة)
// ═══════════════════════════════════════════════════════

function setupTrigger() {
  // امسح الـ triggers القديمة
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(t => {
    if (t.getHandlerFunction() === 'syncFormResponses') {
      ScriptApp.deleteTrigger(t);
    }
  });

  // ⚡ Trigger كل ساعة
  ScriptApp.newTrigger('syncFormResponses')
    .timeBased()
    .everyHours(1)
    .create();

  Logger.log('✅ Trigger created: every hour');
}

// ═══════════════════════════════════════════════════════
//   Test
// ═══════════════════════════════════════════════════════

function testSync() {
  const result = syncFormResponses();
  Logger.log(JSON.stringify(result, null, 2));
}

// ═══════════════════════════════════════════════════════
//   Web App Entry (للاستدعاء من الخارج)
// ═══════════════════════════════════════════════════════

function doGet(e) {
  try {
    const action = e.parameter.action;

    if (action === 'sync') {
      const result = syncFormResponses();
      return jsonResponse(result);
    }

    return jsonResponse({ ok: true, message: 'Sync service is running' });
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function jsonResponse(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
