  if (syncColIndex === -1) {
    syncColIndex = headers.length;
    sheet.getRange(1, syncColIndex + 1).setValue(SYNC_STATUS_COLUMN);
    headers.push(SYNC_STATUS_COLUMN);
  }

  const firestore = getFirestore();

  // ⚡ اجلب كل الأشخاص مرة واحدة
  let allPeople = [];
  try {
    if (typeof firestore.getDocuments === 'function') {
      allPeople = firestore.getDocuments(FIRESTORE_COLLECTION) || [];
    }
  } catch (e) {
    Logger.log('⚠️ Firestore fetch error: ' + e.message);
    allPeople = [];
  }

  let added = 0;
  let updated = 0;
  let skipped = 0;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowNumber = i + 2;

    // تخطى لو متزامن
    const syncedAt = row[syncColIndex];
    if (syncedAt) {
      skipped++;
      continue;
    }

    try {
      const personData = mapRowToPerson(headers, row);

      if (!personData.Email) {
        Logger.log(`⚠️ Row ${rowNumber}: Email missing — skipped`);
        skipped++;
        continue;
      }

      // ⚡ ابحث بالبريد
      const existing = allPeople.find(p =>
        String(p.Email || '').toLowerCase() === personData.Email.toLowerCase()
      );

      if (existing && (existing._id || existing.id)) {
        // ⚡ حدّث
        const docId = existing._id || existing.id;

        if (typeof firestore.updateDocument === 'function') {
          firestore.updateDocument(FIRESTORE_COLLECTION, docId, personData);
        } else {
          FirestoreApp.updateDocument(FIRESTORE_COLLECTION, docId, personData);
        }

        updated++;
        Logger.log(`Updated: ${personData.Email}`);
      } else {
        // ⚡ أضف جديد
        if (typeof firestore.createDocument === 'function') {
          firestore.createDocument(FIRESTORE_COLLECTION, personData);
        } else {
          FirestoreApp.createDocument(FIRESTORE_COLLECTION, personData);
        }

        added++;
        Logger.log(`Added: ${personData.Email}`);
        allPeople.push(personData);
      }

      // ⚡ سجّل المزامنة
      sheet.getRange(rowNumber, syncColIndex + 1).setValue(new Date());

    } catch (err) {
      Logger.log(`❌ Row ${rowNumber}: ${err.message}`);
    }
  }

  Logger.log(`✅ Done: Added=${added}, Updated=${updated}, Skipped=${skipped}`);
  return { ok: true, added, updated, skipped };
}

// ═══════════════════════════════════════════════════════
//   Map Row → Person Object
// ═══════════════════════════════════════════════════════

function mapRowToPerson(headers, row) {
  const get = (name) => {
    const idx = headers.indexOf(name);
    return idx !== -1 ? String(row[idx] || '').trim() : '';
  };

  return {
    FirstName: get('الاسم الأول'),
    SecondName: get('الاسم الثاني'),
    ThirdName: get('الاسم الثالث'),
    FourthName: get('الاسم الرابع'),
    BirthDate: formatDate(get('تاريخ الميلاد')),
    Gender: mapGender(get('النوع')),
    Address: get('العنوان'),
    Mobile: normalizePhone(get('رقم الموبايل')),
    WhatsApp: normalizePhone(get('رقم واتساب')),
    Email: get('البريد الإلكتروني').toLowerCase(),
    Facebook: get('رابط صفحة الفيسبوك (اختياري)'),
    PhotoURL: get('رابط صورتك الشخصية (اختياري)'),
    Status: 'active',
    QRCode: '',
    CreatedAt: new Date().toISOString(),
    Source: 'google_form'
  };
}

function mapGender(v) {
  if (!v) return '';
  if (v === 'ذكر') return 'male';
  if (v === 'أنثى') return 'female';
  return String(v).toLowerCase();
}

function normalizePhone(v) {
  if (!v) return '';
  return String(v).replace(/\s+/g, '').replace(/[^\d+]/g, '');
}

function formatDate(v) {
  if (!v) return '';
  try {
    if (v instanceof Date) {
      return Utilities.formatDate(v, 'Africa/Cairo', 'yyyy-MM-dd');
    }
    const d = new Date(v);
    if (isNaN(d.getTime())) return String(v);
    return Utilities.formatDate(d, 'Africa/Cairo', 'yyyy-MM-dd');
  } catch (e) {
    return String(v);
  }
}

// ═══════════════════════════════════════════════════════
//   Trigger Setup
// ═══════════════════════════════════════════════════════

function setupTrigger() {
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(t => {
    if (t.getHandlerFunction() === 'syncFormResponses') {
      ScriptApp.deleteTrigger(t);
    }
  });

  ScriptApp.newTrigger('syncFormResponses')
    .timeBased()
    .everyHours(1)
    .create();

  Logger.log('✅ Trigger created: every hour');
}

