// ═══════════════════════════════════════════════════════
//   Helpers
// ═══════════════════════════════════════════════════════

function getFullName(person) {
  if (!person) return '';
  return [
    person.FirstName,
    person.SecondName,
    person.ThirdName,
    person.FourthName
  ].filter(Boolean).join(' ');
}

function getInitial(person) {
  return (person?.FirstName || '?').charAt(0);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function parseDate(value) {
  if (!value) return null;
  if (value.toDate) return value.toDate();
  const d = new Date(value);
  return isNaN(d.getTime()) ? null : d;
}

function formatDate(dateStr) {
  if (!dateStr) return '-';
  try {
    const d = parseDate(dateStr);
    if (!d) return dateStr;
    const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
  } catch (e) {
    return dateStr;
  }
}

function formatDateTime(date) {
  if (!date) return '';
  try {
    const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    const h = String(date.getHours()).padStart(2, '0');
    const m = String(date.getMinutes()).padStart(2, '0');
    return `${date.getDate()} ${months[date.getMonth()]} ${date.getFullYear()} - ${h}:${m}`;
  } catch (e) {
    return '';
  }
}

// ═══ Facebook URL Helpers ═══
function formatFacebookUrl(value) {
  if (!value) return '';
  let url = String(value).trim();

  if (url.startsWith('http://') || url.startsWith('https://')) {
    return url;
  }

  if (url.startsWith('facebook.com') ||
      url.startsWith('www.facebook.com') ||
      url.startsWith('m.facebook.com') ||
      url.startsWith('fb.com') ||
      url.startsWith('fb.me')) {
    return 'https://' + url;
  }

  url = url.replace(/^@/, '');
  return 'https://facebook.com/' + url;
}

function getFacebookDisplay(value) {
  if (!value) return '-';
  let url = String(value).trim();

  url = url.replace(/^https?:\/\//, '');
  url = url.replace(/^www\./, '');
  url = url.replace(/^m\./, '');

  return url;
}

