## 📄 1. `Code.gs` كامل بعد التعديل

**افتح Apps Script → `Code.gs` → Ctrl+A → Delete → الصق ده:**

```javascript
// ═══════════════════════════════════════════════════════
//   Sync Google Form Responses → Firestore + Accounts
// ═══════════════════════════════════════════════════════

const SHEET_ID = '1Ak-5RLNfmAFawOsoFdB-YEee6TSQi6XFOGpVWn6hxcE';
const SHEET_NAME = 'Form Responses 1';
const FIRESTORE_PEOPLE = 'people';
const FIRESTORE_ACCOUNTS = 'accounts';
const SYNC_STATUS_COLUMN = 'SyncedAt';
const DEFAULT_ROLE = 'User';

// ═══════════════════════════════════════════════════════
//   Firestore Init
// ═══════════════════════════════════════════════════════

function getFirestore() {
  const props = PropertiesService.getScriptProperties();

  const projectId = props.getProperty('FIREBASE_PROJECT_ID');
  const clientEmail = props.getProperty('FIREBASE_CLIENT_EMAIL');
  let privateKey = props.getProperty('FIREBASE_PRIVATE_KEY');

  if (!projectId || !clientEmail || !privateKey) {
    throw new Error('Firebase credentials not found in Script Properties');
  }

  privateKey = privateKey.replace(/\\n/g, '\n');

  if (typeof FirestoreApp.getFirestore === 'function') {
    return FirestoreApp.getFirestore(clientEmail, privateKey, projectId);
  }

  FirestoreApp.setFirestore(clientEmail, privateKey, projectId);
  return FirestoreApp;
}

// ═══════════════════════════════════════════════════════
//   ⚡ Extract Field from Firestore Document
// ═══════════════════════════════════════════════════════

function getFieldValue(doc, fieldName) {
  if (!doc || !doc.fields || !doc.fields[fieldName]) return '';

  const field = doc.fields[fieldName];

  if (field.stringValue !== undefined) return String(field.stringValue);
  if (field.integerValue !== undefined) return String(field.integerValue);
  if (field.doubleValue !== undefined) return String(field.doubleValue);
  if (field.booleanValue !== undefined) return String(field.booleanValue);
  if (field.timestampValue !== undefined) return String(field.timestampValue);
  if (field.nullValue !== undefined) return '';

  return '';
}

function getDocId(doc) {
  if (!doc || !doc.name) return null;
  const parts = String(doc.name).split('/');
  return parts[parts.length - 1];
}

function docToObject(doc) {
  if (!doc || !doc.fields) return {};

  const obj = { _id: getDocId(doc) };

  Object.keys(doc.fields).forEach(key => {
    obj[key] = getFieldValue(doc, key);
  });

  return obj;
}

// ═══════════════════════════════════════════════════════
//   ⚡ Create/Update Account for Person
// ═══════════════════════════════════════════════════════

/**
 * ينشئ أو يحدّث account في Firestore
 * @param {Object} firestore - Firestore instance
 * @param {Object} personData - بيانات الشخص
 * @param {string} personId - ID الشخص
 * @param {Array} allAccounts - قائمة الحسابات الموجودة
 * @returns {Object} - { action: 'created' | 'updated' | 'skipped', accountId }
 */
function ensureAccountForPerson(firestore, personData, personId, allAccounts) {
  const email = String(personData.Email || '').toLowerCase().trim();

  // ⚡ لو مفيش بريد → ما نعملش account
  if (!email) {
    return { action: 'skipped', reason: 'no_email' };
  }

  // ⚡ دور على account بنفس البريد
  const existing = allAccounts.find(a =>
    String(a.Email || '').toLowerCase().trim() === email
  );

  const accountStatus = String(personData.Status || 'active').toLowerCase() === 'active'
    ? 'active'
    : 'disabled';

  if (existing && existing._id) {
    // ⚡ موجود → حدّث PersonID + Status
    const updateData = {
      PersonID: personId,
      Status: accountStatus,
      UpdatedAt: new Date().toISOString()
    };

    // ⚡ لو الحساب ملوش دور، ضيف User
    if (!existing.Role) {
      updateData.Role = DEFAULT_ROLE;
    }

    if (typeof firestore.updateDocument === 'function') {
      firestore.updateDocument(FIRESTORE_ACCOUNTS, existing._id, updateData);
    } else {
      FirestoreApp.updateDocument(FIRESTORE_ACCOUNTS, existing._id, updateData);
    }

    return { action: 'updated', accountId: existing._id };

  } else {
    // ⚡ مش موجود → أنشئ account جديد
    const newAccount = {
      Email: email,
      Role: DEFAULT_ROLE,
      PersonID: personId,
      Status: accountStatus,
      CreatedAt: new Date().toISOString(),
      Source: 'auto_from_person'
    };

    let newDoc;
    if (typeof firestore.createDocument === 'function') {
      newDoc = firestore.createDocument(FIRESTORE_ACCOUNTS, newAccount);
    } else {
      newDoc = FirestoreApp.createDocument(FIRESTORE_ACCOUNTS, newAccount);
    }

    const newId = newDoc && newDoc.name ? getDocId(newDoc) : 'temp';

    return { action: 'created', accountId: newId };
  }
}

// ═══════════════════════════════════════════════════════
//   Sync Function
// ═══════════════════════════════════════════════════════

function syncFormResponses() {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  const sheet = ss.getSheetByName(SHEET_NAME);

  if (!sheet) {
    throw new Error(`Sheet "${SHEET_NAME}" not found`);
  }

  const data = sheet.getDataRange().getValues();
  if (data.length < 2) {
    Logger.log('لا توجد بيانات للمزامنة');
    return { ok: true, added: 0, updated: 0, skipped: 0, restored: 0, accountsCreated: 0 };
  }

  const headers = data[0];
  const rows = data.slice(1);

  // ⚡ تأكد من وجود عمود SyncedAt
  let syncColIndex = headers.indexOf(SYNC_STATUS_COLUMN);
  if (syncColIndex === -1) {
    syncColIndex = headers.length;
    sheet.getRange(1, syncColIndex + 1).setValue(SYNC_STATUS_COLUMN);
    headers.push(SYNC_STATUS_COLUMN);
  }

  const firestore = getFirestore();

  // ⚡ اجلب people + accounts
  let allPeople = [];
  let allAccounts = [];

  try {
    const rawPeople = firestore.getDocuments(FIRESTORE_PEOPLE) || [];
    allPeople = rawPeople.map(docToObject);
  } catch (e) {
    Logger.log('⚠️ People fetch error: ' + e.message);
    allPeople = [];
  }

  try {
    const rawAccounts = firestore.getDocuments(FIRESTORE_ACCOUNTS) || [];
    allAccounts = rawAccounts.map(docToObject);
  } catch (e) {
    Logger.log('⚠️ Accounts fetch error: ' + e.message);
    allAccounts = [];
  }

  let added = 0;
  let updated = 0;
  let skipped = 0;
  let restored = 0;
  let accountsCreated = 0;
  let accountsUpdated = 0;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowNumber = i + 2;

    try {
      const personData = mapRowToPerson(headers, row);

      if (!personData.Email) {
        Logger.log(`⚠️ Row ${rowNumber}: Email missing — skipped`);
        skipped++;
        continue;
      }

      const emailLower = personData.Email.toLowerCase();
      const existing = allPeople.find(p =>
        String(p.Email || '').toLowerCase() === emailLower
      );

      const syncedAt = row[syncColIndex];

      let personId = null;
      let personAction = '';

      // ═══ 1. الشخص موجود في Firestore ═══
      if (existing && existing._id) {
        personId = existing._id;

        if (syncedAt) {
          skipped++;
        } else {
          // حدّث
          if (typeof firestore.updateDocument === 'function') {
            firestore.updateDocument(FIRESTORE_PEOPLE, personId, personData);
          } else {
            FirestoreApp.updateDocument(FIRESTORE_PEOPLE, personId, personData);
          }

          updated++;
          personAction = 'updated';
          sheet.getRange(rowNumber, syncColIndex + 1).setValue(new Date());
        }
      } else {
        // ═══ 2. الشخص مش موجود → أضف ═══
        let newDoc;
        if (typeof firestore.createDocument === 'function') {
          newDoc = firestore.createDocument(FIRESTORE_PEOPLE, personData);
        } else {
          newDoc = FirestoreApp.createDocument(FIRESTORE_PEOPLE, personData);
        }

        personId = newDoc && newDoc.name ? getDocId(newDoc) : null;

        added++;
        allPeople.push({ _id: personId, ...personData });

        if (syncedAt) {
          restored++;
          Logger.log(`🔄 Restored: ${personData.Email}`);
        } else {
          Logger.log(`➕ Added: ${personData.Email}`);
        }

        personAction = 'added';
        sheet.getRange(rowNumber, syncColIndex + 1).setValue(new Date());
      }

      // ═══ 3. ⚡ أنشئ/حدّث Account ═══
      if (personId && personAction) {
        const accountResult = ensureAccountForPerson(
          firestore,
          personData,
          personId,
          allAccounts
        );

        if (accountResult.action === 'created') {
          accountsCreated++;
          Logger.log(`   👤 Account created for: ${personData.Email}`);
          // ⚡ أضف للقائمة المحلية
          allAccounts.push({
            _id: accountResult.accountId,
            Email: personData.Email,
            Role: DEFAULT_ROLE,
            PersonID: personId
          });
        } else if (accountResult.action === 'updated') {
          accountsUpdated++;
          Logger.log(`   ✏️ Account updated for: ${personData.Email}`);
        }
      }

    } catch (err) {
      Logger.log(`❌ Row ${rowNumber}: ${err.message}`);
    }
  }

  Logger.log(`✅ Done: Added=${added}, Updated=${updated}, Skipped=${skipped}, Restored=${restored}`);
  Logger.log(`👤 Accounts: Created=${accountsCreated}, Updated=${accountsUpdated}`);

  return {
    ok: true,
    added: added,
    updated: updated,
    skipped: skipped,
    restored: restored,
    accountsCreated: accountsCreated,
    accountsUpdated: accountsUpdated
  };
}

// ═══════════════════════════════════════════════════════
//   Map Row → Person Object
// ═══════════════════════════════════════════════════════

function mapRowToPerson(headers, row) {
  const get = (name) => {
    const idx = headers.indexOf(name);
    return idx !== -1 ? String(row[idx] || '').trim() : '';
  };

  const getByIndex = (index) => {
    return String(row[index] || '').trim();
  };

  const firstName = get('الاسم الأول') || getByIndex(1);
  const secondName = get('الاسم الثاني') || getByIndex(2);
  const thirdName = get('الاسم الثالث') || getByIndex(3);
  const fourthName = get('الاسم الرابع') || getByIndex(4);
  const birthDate = get('تاريخ الميلاد') || getByIndex(5);
  const gender = get('النوع') || getByIndex(6);
  const address = get('العنوان') || getByIndex(7);
  const mobile = get('رقم الموبايل') || getByIndex(8);
  const whatsapp = get('رقم واتساب') || getByIndex(9);
  let email = get('البريد الإلكتروني') || getByIndex(10);
  const facebook = get('رابط صفحة الفيسبوك (اختياري)') || getByIndex(11);
  const photoURL = get('رابط صورتك الشخصية (اختياري)') || getByIndex(12);

  if (!email) {
    email = get('Email Address') || getByIndex(13);
  }

  return {
    FirstName: firstName,
    SecondName: secondName,
    ThirdName: thirdName,
    FourthName: fourthName,
    BirthDate: formatDate(birthDate),
    Gender: mapGender(gender),
    Address: address,
    Mobile: normalizePhone(mobile),
    WhatsApp: normalizePhone(whatsapp),
    Email: email.toLowerCase(),
    Facebook: facebook,
    PhotoURL: photoURL,
    Status: 'active',
    QRCode: '',
    CreatedAt: new Date().toISOString(),
    Source: 'google_form'
  };
}

function mapGender(v) {
  if (!v) return '';
  if (v === 'ذكر') return 'male';
  if (v === 'أنثى') return 'female';
  return String(v).toLowerCase();
}

function normalizePhone(v) {
  if (!v) return '';
  return String(v).replace(/\s+/g, '').replace(/[^\d+]/g, '');
}

function formatDate(v) {
  if (!v) return '';
  try {
    if (v instanceof Date) {
      return Utilities.formatDate(v, 'Africa/Cairo', 'yyyy-MM-dd');
    }
    const d = new Date(v);
    if (isNaN(d.getTime())) return String(v);
    return Utilities.formatDate(d, 'Africa/Cairo', 'yyyy-MM-dd');
  } catch (e) {
    return String(v);
  }
}

// ═══════════════════════════════════════════════════════
//   Trigger Setup
// ═══════════════════════════════════════════════════════

function setupTrigger() {
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(t => {
    if (t.getHandlerFunction() === 'syncFormResponses') {
      ScriptApp.deleteTrigger(t);
    }
  });

  ScriptApp.newTrigger('syncFormResponses')
    .timeBased()
    .everyHours(1)
    .create();

  Logger.log('✅ Trigger created: every hour');
}

// ═══════════════════════════════════════════════════════
//   Test
// ═══════════════════════════════════════════════════════

function testSync() {
  try {
    const result = syncFormResponses();
    Logger.log(JSON.stringify(result, null, 2));
  } catch (err) {
    Logger.log('❌ ERROR: ' + err.message);
    Logger.log('Stack: ' + err.stack);
  }
}

// ═══════════════════════════════════════════════════════
//   Web App
// ═══════════════════════════════════════════════════════

function doGet(e) {
  try {
    const action = e.parameter.action;

    if (action === 'sync') {
      const result = syncFormResponses();
      return jsonResponse(result);
    }

    return jsonResponse({ ok: true, message: 'Sync service is running' });
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function doPost(e) {
  try {
    let action = '';

    if (e.postData && e.postData.contents) {
      try {
        const body = JSON.parse(e.postData.contents);
        action = body.action || '';
      } catch (parseErr) {
        action = e.parameter.action || '';
      }
    } else {
      action = e.parameter.action || '';
    }

    if (action === 'sync') {
      const result = syncFormResponses();
      return jsonResponse(result);
    }

    return jsonResponse({ ok: true, message: 'Sync service is running' });
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function jsonResponse(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}
