    settingsData.TabPermissions = DEFAULT_TAB_PERMISSIONS;
    renderTabPermissions();

    alert('✅ تم استعادة الإعدادات الافتراضية');
  } catch (err) {
    console.error('❌ Reset tab permissions error:', err);
    alert('خطأ: ' + err.message);
  }
};

