  const locationMode = meeting ? String(meeting.LocationMode || 'any').toLowerCase() : 'any';
  const locationIds = meeting && Array.isArray(meeting.LocationIds) ? meeting.LocationIds : [];

  const noLocations = availableLocations.length === 0;

