      </div>

      <div class="modal-body">
        <div class="form-row">
          <label>اسم الاجتماع *</label>
          <input type="text" id="meetingTitle" value="${meeting ? escapeHtml(meeting.Title || '') : ''}" placeholder="مثال: اجتماع الشباب" />
