            <select id="meetingDayOfWeek">
              ${DAYS_OF_WEEK.map(d => `
                <option value="${d.value}" ${meeting && meeting.DayOfWeek === d.value ? 'selected' : ''}>${d.label}</option>
              `).join('')}
            </select>
