        </div>

        <!-- ⚡ الوقت: من - إلى -->
        <div class="form-grid-2">
          <div class="form-row">
            <label>وقت البداية *</label>
            <input type="time" id="meetingTime" value="${meeting && meeting.Time ? meeting.Time : '19:00'}" />
          </div>
          <div class="form-row">
            <label>وقت النهاية *</label>
            <input type="time" id="meetingEndTime" value="${endTime}" />
