        </div>
        <p class="hint">تأكد أن وقت النهاية بعد وقت البداية</p>

        <div class="form-row checkbox-row">
          <input type="checkbox" id="meetingActive" ${!meeting || String(meeting.Status || 'active').toLowerCase() === 'active' ? 'checked' : ''} />
