// ⚡ helper للحصول على EndTime
function getMeetingEndTime(meeting) {
  if (!meeting) return '';

  if (meeting.EndTime) return String(meeting.EndTime);

  const time = String(meeting.Time || '00:00');
  const [h, m] = time.split(':').map(Number);

