}

function getLocationsInfoText(meeting) {
  const mode = String(meeting.LocationMode || 'any').toLowerCase();
  if (mode === 'any') return `<span style="color:#16a34a;">أي مكان مسجل</span>`;

  const ids = Array.isArray(meeting.LocationIds) ? meeting.LocationIds : [];
  if (ids.length === 0) return `<span style="color:#d97706;">لم يتم تحديد أماكن</span>`;

  const names = ids.map(id => {
    const loc = availableLocations.find(l => l.id === id);
    return loc ? loc.name : 'مكان محذوف';
  });

  if (mode === 'single') return escapeHtml(names[0] || 'مكان محدد');
  return escapeHtml(names.join(' • '));
}

// ═══════════════════════════════════════════════════════
//   Filters
// ═══════════════════════════════════════════════════════

function setupMeetingsEvents() {
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.onclick = () => {
      currentFilter = btn.dataset.filter;
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      applyFilter();
    };
  });
}

function applyFilter() {
  const isView = currentMode === 'view';
  const baseData = isView
    ? meetingsData.filter(m => String(m.Status || '').toLowerCase() === 'active')
    : meetingsData;

  if (currentFilter === 'all') filteredMeetings = [...baseData];
  else if (currentFilter === 'active') filteredMeetings = baseData.filter(m => String(m.Status || '').toLowerCase() === 'active');
  else if (currentFilter === 'inactive') filteredMeetings = baseData.filter(m => String(m.Status || '').toLowerCase() === 'inactive');
  else if (currentFilter === 'weekly') filteredMeetings = baseData.filter(m => String(m.Type || '').toLowerCase() === 'weekly');
  else if (currentFilter === 'once') filteredMeetings = baseData.filter(m => String(m.Type || '').toLowerCase() === 'once');
  else if (currentFilter === 'archived') filteredMeetings = baseData.filter(m => String(m.Status || '').toLowerCase() === 'archived');

  renderMeetingsGrid();
}

// ═══════════════════════════════════════════════════════
