// ═══════════════════════════════════════════════════════
//   Save Meeting
// ═══════════════════════════════════════════════════════

async function saveMeeting() {
  if (currentMode === 'view') {
    alert('غير مصرح لك بحفظ الاجتماعات');
    return;
  }

  const title = document.getElementById('meetingTitle')?.value.trim();
  const type = document.getElementById('meetingType')?.value;
  const date = document.getElementById('meetingDate')?.value || '';
  const dayOfWeek = document.getElementById('meetingDayOfWeek')?.value || '';
  const time = document.getElementById('meetingTime')?.value || '';
  const endTime = document.getElementById('meetingEndTime')?.value || '';
  const isActive = document.getElementById('meetingActive')?.checked;

  if (!title) { alert('اسم الاجتماع مطلوب'); return; }
  if (type === 'once' && !date) { alert('التاريخ مطلوب'); return; }
  if (type === 'weekly' && !dayOfWeek) { alert('يوم الأسبوع مطلوب'); return; }
  if (!time) { alert('وقت البداية مطلوب'); return; }
  if (!endTime) { alert('وقت النهاية مطلوب'); return; }

  if (!isEndTimeAfterStart(time, endTime)) {
    alert(`❌ وقت النهاية يجب أن يكون بعد وقت البداية.\n\nالبداية: ${time}\nالنهاية: ${endTime}`);
    return;
  }

  if (type === 'once') {
    if (isDateInPast(date)) {
      alert(`❌ لا يمكن إضافة اجتماع بتاريخ قديم.\n\nالتاريخ: ${date}\nاليوم: ${formatDateISO(new Date())}`);
      return;
    }
    if (isTimeInPast(date, time)) {
      alert(`❌ الوقت المحدد قد فات.\n\nالآن: ${formatTimeNow()}\nالمحدد: ${time}`);
      return;
    }
  }

  if (type === 'weekly' && isWeeklyTimeInPast(dayOfWeek, time)) {
    const dayLabel = getDayLabel(dayOfWeek);
    alert(`❌ اجتماع "${dayLabel}" الساعة ${time} قد فات.\n\nالآن: ${formatTimeNow()}`);
    return;
  }

  let locationMode = 'any';
  let locationIds = [];

  const modeRadio = document.querySelector('input[name="locationMode"]:checked');
  if (modeRadio) locationMode = modeRadio.value;

  if (locationMode === 'single') {
    const singleVal = document.getElementById('singleLocationSelect')?.value;
    if (!singleVal) { alert('اختر مكان واحد على الأقل'); return; }
    locationIds = [singleVal];
  } else if (locationMode === 'multiple') {
    const checked = document.querySelectorAll('#multipleLocationsBox input[type="checkbox"]:checked');
    locationIds = Array.from(checked).map(c => c.value);
    if (locationIds.length === 0) { alert('اختر مكان واحد على الأقل'); return; }
  }

  const status = isActive ? 'active' : 'cancelled';

  try {
    if (currentEditId) {
      const meetingRef = doc(db, COLLECTIONS.MEETINGS, currentEditId);
      await updateDoc(meetingRef, {
        Title: title,
        Type: type,
        Date: type === 'once' ? date : '',
        DayOfWeek: type === 'weekly' ? dayOfWeek : '',
        Time: time,
        EndTime: endTime,
        Status: status,
        LocationMode: locationMode,
        LocationIds: locationIds,
        UpdatedAt: new Date().toISOString()
      });
      alert('✅ تم التعديل بنجاح');
    } else {
      const user = JSON.parse(localStorage.getItem('currentUser'));
      await addDoc(collection(db, COLLECTIONS.MEETINGS), {
        Title: title,
        Type: type,
        Date: type === 'once' ? date : '',
        DayOfWeek: type === 'weekly' ? dayOfWeek : '',
        Time: time,
        EndTime: endTime,
        Status: status,
        LocationMode: locationMode,
        LocationIds: locationIds,
        CreatedAt: new Date().toISOString(),
        CreatedBy: user?.email || '',
        CanceledOccurrences: []
      });
      alert('✅ تمت الإضافة بنجاح');
    }

    closeMeetingModal();
    const area = document.getElementById('contentArea');
    await loadMeetingsPage(area, currentMode);
  } catch (err) {
    console.error('❌ Save meeting error:', err);
    alert('خطأ: ' + err.message);
  }
}

