function isMeetingOpen(meeting) {
  const today = new Date();
  const occurrenceDate = getTodayOccurrence(meeting);

  if (!occurrenceDate) return false;

  const [hours, minutes] = String(meeting.Time || '00:00').split(':').map(Number);
