```javascript
// ═══════════════════════════════════════════════════════
//   ⚡ Auto Deactivate Once Meetings (Trigger)
// ═══════════════════════════════════════════════════════

function autoDeactivateOnceMeetings() {
  try {
    const firestore = getFirestore();

    let closeAfter = 15;
    try {
      const settingsDoc = firestore.getDocument('settings', 'main');
      if (settingsDoc && settingsDoc.fields) {
        const closeAfterField = getFieldValue(settingsDoc, 'CloseAfterMinutes');
        if (closeAfterField) closeAfter = Number(closeAfterField);
      }
    } catch (e) {
      Logger.log('⚠️ Settings fetch error: ' + e.message);
    }

    const rawMeetings = firestore.getDocuments('meetings') || [];
    const now = new Date();

    let deactivated = 0;

    rawMeetings.forEach(doc => {
      const meeting = docToObject(doc);

      if (String(meeting.Type || '').toLowerCase() !== 'once') return;
      if (String(meeting.Status || '').toLowerCase() !== 'active') return;
      if (!meeting.Date) return;

      let endTime = meeting.EndTime;
      if (!endTime) {
        const [h, m] = String(meeting.Time || '00:00').split(':').map(Number);
        const totalMinutes = (h || 0) * 60 + (m || 0) + 120;
        const newH = Math.floor(totalMinutes / 60) % 24;
        const newM = totalMinutes % 60;
        endTime = `${String(newH).padStart(2, '0')}:${String(newM).padStart(2, '0')}`;
      }

      const [eh, em] = endTime.split(':').map(Number);
      const meetingEnd = new Date(meeting.Date + 'T00:00:00');
      meetingEnd.setHours(eh || 0, em || 0, 0, 0);
      const closeTime = new Date(meetingEnd.getTime() + closeAfter * 60 * 1000);

      if (now > closeTime && meeting._id) {
        try {
          if (typeof firestore.updateDocument === 'function') {
            firestore.updateDocument('meetings', meeting._id, {
              Status: 'inactive',
              DeactivatedAt: now.toISOString(),
              AutoDeactivated: true
            });
          } else {
            FirestoreApp.updateDocument('meetings', meeting._id, {
              Status: 'inactive',
              DeactivatedAt: now.toISOString(),
              AutoDeactivated: true
            });
          }
          deactivated++;
        } catch (e) {
          Logger.log(`❌ Failed to deactivate ${meeting._id}: ${e.message}`);
        }
      }
    });

    Logger.log(`✅ Deactivated ${deactivated} once meeting(s)`);
    return { ok: true, deactivated: deactivated };
  } catch (err) {
    Logger.log('❌ autoDeactivateOnceMeetings error: ' + err.message);
    return { ok: false, message: err.message };
  }
}

function setupAutoDeactivateTrigger() {
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(t => {
    if (t.getHandlerFunction() === 'autoDeactivateOnceMeetings') {
      ScriptApp.deleteTrigger(t);
    }
  });

  ScriptApp.newTrigger('autoDeactivateOnceMeetings')
    .timeBased()
    .everyHours(1)
    .create();

  Logger.log('✅ Auto-deactivate trigger created: every hour');
}

function testAutoDeactivate() {
  const result = autoDeactivateOnceMeetings();
  Logger.log(JSON.stringify(result, null, 2));
}
