  }

  container.innerHTML = `
    <div style="text-align:center;margin-bottom:20px;">
      <h2 style="color:var(--text);margin-bottom:6px;">مرحبًا ${escapeHtml(fullName)}</h2>
      <p style="color:var(--text-muted);font-size:14px;">سجّل حضورك بمسح QR النظام</p>
