        }).join('')}
      </select>

      <div id="maMeetingInfo" class="ma-meeting-info" style="display:none;"></div>
    </div>

    <div class="ma-step" id="maScanStep" style="display:none;">
      <div class="ma-step-title">
        <span class="step-num">2</span>
