// ═══════════════════════════════════════════════════════
//   Events
// ═══════════════════════════════════════════════════════

function setupMyAttendanceEvents() {
  const select = document.getElementById('maMeetingSelect');
  const scanBtn = document.getElementById('maScanBtn');

  if (select) {
    select.onchange = () => {
      const meetingId = select.value;

      if (!meetingId) {
        maSelectedMeeting = null;
