```javascript
// ═══════════════════════════════════════════════════════
//   Migration: meetings → events
//              churches → locations
//              attendance.MeetingID → EventID
// ═══════════════════════════════════════════════════════

const FIRESTORE_EVENTS = 'events';
const FIRESTORE_LOCATIONS = 'locations';
const FIRESTORE_ATTENDANCE = 'attendance';
const FIRESTORE_MEETINGS = 'meetings';
const FIRESTORE_CHURCHES = 'churches';
const FIRESTORE_EVENT_TYPES = 'eventTypes';
const FIRESTORE_SETTINGS = 'settings';

// ═══════════════════════════════════════════════════════
//   Main Migration
// ═══════════════════════════════════════════════════════

function runFullMigration() {
  Logger.log('🚀 بدء Migration الكامل...');
  Logger.log('═══════════════════════════════════════════');

  const results = {
    eventsMigrated: 0,
    eventsSkipped: 0,
    locationsMigrated: 0,
    locationsSkipped: 0,
    attendanceUpdated: 0,
    attendanceSkipped: 0,
    errors: []
  };

  try {
    const firestore = getFirestore();

    // ═══ 1. Migration: meetings → events ═══
    Logger.log('\n📦 Migration: meetings → events');
    const meetingsResult = migrateMeetingsToEvents(firestore);
    results.eventsMigrated = meetingsResult.migrated;
    results.eventsSkipped = meetingsResult.skipped;
    results.errors.push(...meetingsResult.errors);

    // ═══ 2. Migration: churches → locations ═══
    Logger.log('\n📦 Migration: churches → locations');
    const churchesResult = migrateChurchesToLocations(firestore);
    results.locationsMigrated = churchesResult.migrated;
    results.locationsSkipped = churchesResult.skipped;
    results.errors.push(...churchesResult.errors);

    // ═══ 3. Update: attendance.MeetingID → EventID ═══
    Logger.log('\n📦 Update: attendance.MeetingID → EventID');
    const attendanceResult = updateAttendanceFields(firestore);
    results.attendanceUpdated = attendanceResult.updated;
    results.attendanceSkipped = attendanceResult.skipped;
    results.errors.push(...attendanceResult.errors);

    // ═══ 4. Update: settings — أضف ActiveMassTemplateID ═══
    Logger.log('\n📦 Update: settings/main');
    updateSettingsField(firestore);

    // ═══ ملخص ═══
    Logger.log('\n═══════════════════════════════════════════');
    Logger.log('✅ Migration خلص بنجاح');
    Logger.log(`   Events: ${results.eventsMigrated} مضاف، ${results.eventsSkipped} متجاهل`);
    Logger.log(`   Locations: ${results.locationsMigrated} مضاف، ${results.locationsSkipped} متجاهل`);
    Logger.log(`   Attendance: ${results.attendanceUpdated} معدّل، ${results.attendanceSkipped} متجاهل`);
    if (results.errors.length > 0) {
      Logger.log(`   ⚠️ Errors: ${results.errors.length}`);
      results.errors.forEach(e => Logger.log(`      - ${e}`));
    }

    return results;
  } catch (err) {
    Logger.log('❌ Migration فشل: ' + err.message);
    Logger.log('Stack: ' + err.stack);
    return { ok: false, error: err.message };
  }
}

// ═══════════════════════════════════════════════════════
//   1. Migrate meetings → events
// ═══════════════════════════════════════════════════════

function migrateMeetingsToEvents(firestore) {
  const result = { migrated: 0, skipped: 0, errors: [] };

  try {
    // ⚡ اجلب meetings الحالية
    const rawMeetings = firestore.getDocuments(FIRESTORE_MEETINGS) || [];
    if (rawMeetings.length === 0) {
      Logger.log('   ⚠️ مفيش meetings للحفظ');
      return result;
    }

    // ⚡ اجلب events الموجودة (عشان منعملش تكرار)
    let existingEvents = [];
    try {
      existingEvents = firestore.getDocuments(FIRESTORE_EVENTS) || [];
    } catch (e) {
      existingEvents = [];
    }
    const existingIds = existingEvents.map(e => getDocId(e));

    // ⚡ اجلب الإعدادات لـ ActiveMassTemplateID
    let activeTemplateId = 'template_normal';
    try {
      const settingsDoc = firestore.getDocument(FIRESTORE_SETTINGS, 'main');
      if (settingsDoc && settingsDoc.fields) {
        const t = getFieldValue(settingsDoc, 'ActiveMassTemplateID');
        if (t) activeTemplateId = t;
      }
    } catch (e) {}

    for (const doc of rawMeetings) {
      const meetingId = getDocId(doc);
      const meeting = docToObject(doc);

      try {
        // ⚡ استخرج حقول meetings
        const eventData = {
          // ⚡ بيانات أساسية
          Title: meeting.Title || 'بدون عنوان',
          EventTypeID: 'type_meeting',  // الاجتماعات → اجتماع
          Type: meeting.Type || 'once', // weekly | once

          // ⚡ التاريخ
          DayOfWeek: meeting.DayOfWeek || '',
          Date: meeting.Date || '',

          // ⚡ الوقت
          Time: meeting.Time || '19:00',
          EndTime: meeting.EndTime || '21:00',

          // ⚡ المكان
          LocationID: extractLocationId(meeting) || '',
          LocationMode: meeting.LocationMode || 'any',
          LocationIds: meeting.LocationIds || [],

          // ⚡ التسجيل (افتراضي: all)
          RegistrationScope: 'all',

          // ⚡ القواعد
          Rules: {
            RequiresQR: true,
            RequiresLocation: meeting.LocationMode !== 'any' ? true : false,
            PreventDuplicate: true
          },

          // ⚡ النمط
          TemplateID: activeTemplateId,

          // ⚡ الحالة
          Status: normalizeStatus(meeting.Status),
          CanceledOccurrences: meeting.CanceledOccurrences || [],

          // ⚡ بيانات إضافية
          CreatedAt: meeting.CreatedAt || new Date().toISOString(),
          CreatedBy: meeting.CreatedBy || '',
          MigratedFrom: 'meetings',
          MigratedAt: new Date().toISOString()
        };

        // ⚡ لو الحدث migrated قبل كده، تجاهل
        if (existingIds.includes('evt_' + meetingId)) {
          result.skipped++;
          continue;
        }

        // ⚡ أنشئ event جديد
        const newEventId = 'evt_' + meetingId;
        if (typeof firestore.createDocument === 'function') {
          firestore.createDocument(FIRESTORE_EVENTS, eventData, newEventId);
        } else {
          FirestoreApp.createDocument(FIRESTORE_EVENTS, eventData, newEventId);
        }

        result.migrated++;
        Logger.log(`   ➕ Event: ${eventData.Title} (${newEventId})`);

      } catch (err) {
        result.errors.push(`Meeting ${meetingId}: ${err.message}`);
        Logger.log(`   ❌ ${meetingId}: ${err.message}`);
      }
    }
  } catch (err) {
    result.errors.push('migrateMeetingsToEvents: ' + err.message);
  }

  return result;
}

// ═══════════════════════════════════════════════════════
//   2. Migrate churches → locations
// ═══════════════════════════════════════════════════════

function migrateChurchesToLocations(firestore) {
  const result = { migrated: 0, skipped: 0, errors: [] };

  try {
    // ⚡ churches القديمة كانت مخزنة في settings/main.Locations
    const settingsDoc = firestore.getDocument(FIRESTORE_SETTINGS, 'main');
    if (!settingsDoc || !settingsDoc.fields) {
      Logger.log('   ⚠️ مفيش settings/main');
      return result;
    }

    // ⚡ اقرأ Locations من settings (الشكل القديم)
    let oldLocations = [];
    try {
      const locField = settingsDoc.fields.Locations;
      if (locField && locField.arrayValue && locField.arrayValue.values) {
        oldLocations = locField.arrayValue.values.map(v => {
          const obj = {};
          if (v.mapValue && v.mapValue.fields) {
            Object.keys(v.mapValue.fields).forEach(k => {
              obj[k] = getFieldValue({ fields: v.mapValue.fields }, k);
            });
          }
          return obj;
        });
      }
    } catch (e) {
      Logger.log('   ⚠️ Locations parse error: ' + e.message);
    }

    if (oldLocations.length === 0) {
      Logger.log('   ⚠️ مفيش locations للحفظ');
      return result;
    }

    // ⚡ اجلب locations الموجودة
    let existingLocations = [];
    try {
      existingLocations = firestore.getDocuments(FIRESTORE_LOCATIONS) || [];
    } catch (e) {
      existingLocations = [];
    }
    const existingIds = existingLocations.map(l => getDocId(l));

    for (const loc of oldLocations) {
      try {
        const locId = loc.id || ('loc_' + Date.now());

        if (existingIds.includes(locId)) {
          result.skipped++;
          continue;
        }

        const locationData = {
          LocationID: locId,
          Name: loc.name || 'بدون اسم',
          Lat: parseFloat(loc.lat) || 0,
          Lng: parseFloat(loc.lng) || 0,
          Radius: parseInt(loc.radius) || 4,
          Tolerance: parseInt(loc.tolerance) || 15,
          QRCode: loc.qrCode || '',
          Category: 'church',
          Status: 'active',
          CreatedAt: loc.createdAt || new Date().toISOString(),
          MigratedFrom: 'settings.Locations',
          MigratedAt: new Date().toISOString()
        };

        if (typeof firestore.createDocument === 'function') {
          firestore.createDocument(FIRESTORE_LOCATIONS, locationData, locId);
        } else {
          FirestoreApp.createDocument(FIRESTORE_LOCATIONS, locationData, locId);
        }

        result.migrated++;
        Logger.log(`   ➕ Location: ${locationData.Name} (${locId})`);

      } catch (err) {
        result.errors.push(`Location ${loc.id}: ${err.message}`);
        Logger.log(`   ❌ ${loc.name}: ${err.message}`);
      }
    }
  } catch (err) {
    result.errors.push('migrateChurchesToLocations: ' + err.message);
  }

  return result;
}

// ═══════════════════════════════════════════════════════
//   3. Update attendance: MeetingID → EventID
// ═══════════════════════════════════════════════════════

function updateAttendanceFields(firestore) {
  const result = { updated: 0, skipped: 0, errors: [] };

  try {
    const rawAttendance = firestore.getDocuments(FIRESTORE_ATTENDANCE) || [];
    if (rawAttendance.length === 0) {
      Logger.log('   ⚠️ مفيش attendance');
      return result;
    }

    for (const doc of rawAttendance) {
      const attId = getDocId(doc);
      const att = docToObject(doc);

      try {
        // ⚡ لو اتحدّث قبل كده
        if (att.EventID) {
          result.skipped++;
          continue;
        }

        const meetingId = att.MeetingID;
        if (!meetingId) {
          result.skipped++;
          continue;
        }

        const updateData = {
          EventID: 'evt_' + meetingId,
          EventTitle: att.MeetingTitle || '',
          EventTypeID: 'type_meeting',
          MigratedFrom: 'attendance.MeetingID',
          MigratedAt: new Date().toISOString()
        };

        if (typeof firestore.updateDocument === 'function') {
          firestore.updateDocument(FIRESTORE_ATTENDANCE, attId, updateData);
        } else {
          FirestoreApp.updateDocument(FIRESTORE_ATTENDANCE, attId, updateData);
        }

        result.updated++;

      } catch (err) {
        result.errors.push(`Attendance ${attId}: ${err.message}`);
      }
    }

    Logger.log(`   ✅ ${result.updated} attendance معدّل`);
  } catch (err) {
    result.errors.push('updateAttendanceFields: ' + err.message);
  }

  return result;
}

// ═══════════════════════════════════════════════════════
//   4. Update settings/main
// ═══════════════════════════════════════════════════════

function updateSettingsField(firestore) {
  try {
    const updateData = {
      ActiveMassTemplateID: 'template_normal',
      MigrationCompletedAt: new Date().toISOString()
    };

    if (typeof firestore.updateDocument === 'function') {
      firestore.updateDocument(FIRESTORE_SETTINGS, 'main', updateData);
    } else {
      FirestoreApp.updateDocument(FIRESTORE_SETTINGS, 'main', updateData);
    }

    Logger.log('   ✅ settings/main محدّث');
  } catch (err) {
    Logger.log('   ❌ settings update: ' + err.message);
  }
}

// ═══════════════════════════════════════════════════════
//   Helpers
// ═══════════════════════════════════════════════════════

function extractLocationId(meeting) {
  // ⚡ لو فيه LocationIds، خد الأول
  if (meeting.LocationIds && Array.isArray(meeting.LocationIds) && meeting.LocationIds.length > 0) {
    return meeting.LocationIds[0];
  }
  // ⚡ لو فيه LocationID مباشر
  if (meeting.LocationID) return meeting.LocationID;
  return '';
}

function normalizeStatus(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'active') return 'active';
  if (s === 'cancelled') return 'cancelled';
  if (s === 'inactive') return 'inactive';
  if (s === 'archived') return 'archived';
  return 'active';
}

// ═══════════════════════════════════════════════════════
//   Rollback (في حال حصلت مشكلة)
// ═══════════════════════════════════════════════════════

function rollbackMigration() {
  Logger.log('⚠️ Rollback: سيتم حذف events اللي اتعمل لها migration');

  const firestore = getFirestore();
  const rawEvents = firestore.getDocuments(FIRESTORE_EVENTS) || [];

  let deleted = 0;
  for (const doc of rawEvents) {
    const evt = docToObject(doc);
    if (evt.MigratedFrom === 'meetings') {
      const evtId = getDocId(doc);
      try {
        if (typeof firestore.deleteDocument === 'function') {
          firestore.deleteDocument(FIRESTORE_EVENTS, evtId);
        } else {
          FirestoreApp.deleteDocument(FIRESTORE_EVENTS, evtId);
        }
        deleted++;
      } catch (e) {
        Logger.log(`❌ ${evtId}: ${e.message}`);
      }
    }
  }

  Logger.log(`✅ تم حذف ${deleted} event`);
}

