// ═══════════════════════════════════════════════════════
//   Helpers
// ═══════════════════════════════════════════════════════

function extractLocationId(meeting) {
  if (meeting.LocationIds && Array.isArray(meeting.LocationIds) && meeting.LocationIds.length > 0) {
    return meeting.LocationIds[0];
  }
  if (meeting.LocationID) return meeting.LocationID;
  return '';
}

function normalizeStatus(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'active') return 'active';
  if (s === 'cancelled') return 'cancelled';
  if (s === 'inactive') return 'inactive';
  if (s === 'archived') return 'archived';
  return 'active';
}

