### 3. `migrateChurchesToLocations`

```javascript
function migrateChurchesToLocations(firestore) {
  const result = { migrated: 0, skipped: 0, errors: [] };

  try {
    // ⚡ الحل: نقرأ settings/main بالـ path الكامل
    const settingsDoc = firestore.getDocument('settings/main');
    if (!settingsDoc || !settingsDoc.fields) {
      Logger.log('   ⚠️ مفيش settings/main');
      return result;
    }

    let oldLocations = [];
    try {
      const locField = settingsDoc.fields.Locations;
      if (locField && locField.arrayValue && locField.arrayValue.values) {
        oldLocations = locField.arrayValue.values.map(v => {
          const obj = {};
          if (v.mapValue && v.mapValue.fields) {
            Object.keys(v.mapValue.fields).forEach(k => {
              obj[k] = getFieldValue({ fields: v.mapValue.fields }, k);
            });
          }
          return obj;
        });
      }
    } catch (e) {
      Logger.log('   ⚠️ Locations parse error: ' + e.message);
    }

    if (oldLocations.length === 0) {
      Logger.log('   ⚠️ مفيش locations للحفظ');
      return result;
    }

    let existingLocations = [];
    try {
      existingLocations = firestore.getDocuments('locations') || [];
    } catch (e) {
      existingLocations = [];
    }
    const existingIds = existingLocations.map(l => getDocId(l));

    for (const loc of oldLocations) {
      try {
        const locId = loc.id || ('loc_' + Date.now());

        if (existingIds.includes(locId)) {
          result.skipped++;
          continue;
        }

        const locationData = {
          LocationID: locId,
          Name: loc.name || 'بدون اسم',
          Lat: parseFloat(loc.lat) || 0,
          Lng: parseFloat(loc.lng) || 0,
          Radius: parseInt(loc.radius) || 4,
          Tolerance: parseInt(loc.tolerance) || 15,
          QRCode: loc.qrCode || '',
          Category: 'church',
          Status: 'active',
          CreatedAt: loc.createdAt || new Date().toISOString(),
          MigratedFrom: 'settings.Locations',
          MigratedAt: new Date().toISOString()
        };

        if (typeof firestore.createDocument === 'function') {
          firestore.createDocument('locations', locationData, locId);
        } else {
          FirestoreApp.createDocument('locations', locationData, locId);
        }

        result.migrated++;
        Logger.log(`   ➕ Location: ${locationData.Name} (${locId})`);

      } catch (err) {
        result.errors.push(`Location ${loc.id}: ${err.message}`);
        Logger.log(`   ❌ ${loc.name}: ${err.message}`);
      }
    }
  } catch (err) {
    result.errors.push('migrateChurchesToLocations: ' + err.message);
  }

  return result;
}
