## 📄 `Migration.gs` كامل

```javascript
// ═══════════════════════════════════════════════════════
//   Migration: meetings → events
//              churches → locations
//              attendance.MeetingID → EventID
// ═══════════════════════════════════════════════════════

// ⚡ Main Migration
function runFullMigration() {
  Logger.log('🚀 بدء Migration الكامل...');
  Logger.log('═══════════════════════════════════════════');

  const results = {
    eventsMigrated: 0,
    eventsSkipped: 0,
    locationsMigrated: 0,
    locationsSkipped: 0,
    attendanceUpdated: 0,
    attendanceSkipped: 0,
    errors: []
  };

  try {
    const firestore = getFirestore();

    // ═══ 1. Migration: meetings → events ═══
    Logger.log('\n📦 Migration: meetings → events');
    const meetingsResult = migrateMeetingsToEvents(firestore);
    results.eventsMigrated = meetingsResult.migrated;
    results.eventsSkipped = meetingsResult.skipped;
    results.errors.push(...meetingsResult.errors);

    // ═══ 2. Migration: churches → locations ═══
    Logger.log('\n📦 Migration: churches → locations');
    const churchesResult = migrateChurchesToLocations(firestore);
    results.locationsMigrated = churchesResult.migrated;
    results.locationsSkipped = churchesResult.skipped;
    results.errors.push(...churchesResult.errors);

    // ═══ 3. Update: attendance.MeetingID → EventID ═══
    Logger.log('\n📦 Update: attendance.MeetingID → EventID');
    const attendanceResult = updateAttendanceFields(firestore);
    results.attendanceUpdated = attendanceResult.updated;
    results.attendanceSkipped = attendanceResult.skipped;
    results.errors.push(...attendanceResult.errors);

    // ═══ 4. Update: settings — أضف ActiveMassTemplateID ═══
    Logger.log('\n📦 Update: settings/main');
    updateSettingsField(firestore);

    // ═══ ملخص ═══
    Logger.log('\n═══════════════════════════════════════════');
    Logger.log('✅ Migration خلص بنجاح');
    Logger.log(`   Events: ${results.eventsMigrated} مضاف، ${results.eventsSkipped} متجاهل`);
    Logger.log(`   Locations: ${results.locationsMigrated} مضاف، ${results.locationsSkipped} متجاهل`);
    Logger.log(`   Attendance: ${results.attendanceUpdated} معدّل، ${results.attendanceSkipped} متجاهل`);
    if (results.errors.length > 0) {
      Logger.log(`   ⚠️ Errors: ${results.errors.length}`);
      results.errors.forEach(e => Logger.log(`      - ${e}`));
    }

    return results;
  } catch (err) {
    Logger.log('❌ Migration فشل: ' + err.message);
    Logger.log('Stack: ' + err.stack);
    return { ok: false, error: err.message };
  }
}

// ═══════════════════════════════════════════════════════
//   1. Migrate meetings → events
// ═══════════════════════════════════════════════════════

function migrateMeetingsToEvents(firestore) {
  const result = { migrated: 0, skipped: 0, errors: [] };

  try {
    const rawMeetings = firestore.getDocuments('meetings') || [];
    if (rawMeetings.length === 0) {
      Logger.log('   ⚠️ مفيش meetings للحفظ');
      return result;
    }

    let existingEvents = [];
    try {
      existingEvents = firestore.getDocuments('events') || [];
    } catch (e) {
      existingEvents = [];
    }
    const existingIds = existingEvents.map(e => getDocId(e));

    let activeTemplateId = 'template_normal';
    try {
      const settingsDoc = firestore.getDocument('settings/main');
      if (settingsDoc && settingsDoc.fields) {
        const t = getFieldValue(settingsDoc, 'ActiveMassTemplateID');
        if (t) activeTemplateId = t;
      }
    } catch (e) {}

    for (const doc of rawMeetings) {
      const meetingId = getDocId(doc);
      const meeting = docToObject(doc);

      try {
        const eventData = {
          Title: meeting.Title || 'بدون عنوان',
          EventTypeID: 'type_meeting',
          Type: meeting.Type || 'once',
          DayOfWeek: meeting.DayOfWeek || '',
          Date: meeting.Date || '',
          Time: meeting.Time || '19:00',
          EndTime: meeting.EndTime || '21:00',
          LocationID: extractLocationId(meeting) || '',
          LocationMode: meeting.LocationMode || 'any',
          LocationIds: meeting.LocationIds || [],
          RegistrationScope: 'all',
          Rules: {
            RequiresQR: true,
            RequiresLocation: meeting.LocationMode !== 'any' ? true : false,
            PreventDuplicate: true
          },
          TemplateID: activeTemplateId,
          Status: normalizeStatus(meeting.Status),
          CanceledOccurrences: meeting.CanceledOccurrences || [],
          CreatedAt: meeting.CreatedAt || new Date().toISOString(),
          CreatedBy: meeting.CreatedBy || '',
          MigratedFrom: 'meetings',
          MigratedAt: new Date().toISOString()
        };

        if (existingIds.includes('evt_' + meetingId)) {
          result.skipped++;
          continue;
        }

        const newEventId = 'evt_' + meetingId;
        if (typeof firestore.createDocument === 'function') {
          firestore.createDocument('events', eventData, newEventId);
        } else {
          FirestoreApp.createDocument('events', eventData, newEventId);
        }

        result.migrated++;
        Logger.log(`   ➕ Event: ${eventData.Title} (${newEventId})`);

      } catch (err) {
        result.errors.push(`Meeting ${meetingId}: ${err.message}`);
        Logger.log(`   ❌ ${meetingId}: ${err.message}`);
      }
    }
  } catch (err) {
    result.errors.push('migrateMeetingsToEvents: ' + err.message);
  }

  return result;
}

