// ═══════════════════════════════════════════════════════
//   3. Update attendance: MeetingID → EventID
// ═══════════════════════════════════════════════════════

function updateAttendanceFields(firestore) {
  const result = { updated: 0, skipped: 0, errors: [] };

  try {
    const rawAttendance = firestore.getDocuments('attendance') || [];
    if (rawAttendance.length === 0) {
      Logger.log('   ⚠️ مفيش attendance');
      return result;
    }

    for (const doc of rawAttendance) {
      const attId = getDocId(doc);
      const att = docToObject(doc);

      try {
        if (att.EventID) {
          result.skipped++;
          continue;
        }

        const meetingId = att.MeetingID;
        if (!meetingId) {
          result.skipped++;
          continue;
        }

        const updateData = {
          EventID: 'evt_' + meetingId,
          EventTitle: att.MeetingTitle || '',
          EventTypeID: 'type_meeting',
          MigratedFrom: 'attendance.MeetingID',
          MigratedAt: new Date().toISOString()
        };

        // ⚡ نمرّر الـ path الكامل: 'attendance/ID'
        const fullPath = 'attendance/' + attId;

        if (typeof firestore.updateDocument === 'function') {
          firestore.updateDocument(fullPath, updateData);
        } else {
          FirestoreApp.updateDocument(fullPath, updateData);
        }

        result.updated++;

      } catch (err) {
        result.errors.push(`Attendance ${attId}: ${err.message}`);
      }
    }

    Logger.log(`   ✅ ${result.updated} attendance معدّل`);
  } catch (err) {
    result.errors.push('updateAttendanceFields: ' + err.message);
  }

  return result;
}

// ═══════════════════════════════════════════════════════
//   4. Update settings/main
// ═══════════════════════════════════════════════════════

function updateSettingsField(firestore) {
  try {
    const updateData = {
      ActiveMassTemplateID: 'template_normal',
      MigrationCompletedAt: new Date().toISOString()
    };

    // ⚡ نمرّر الـ path الكامل: 'settings/main'
    const fullPath = 'settings/main';

    if (typeof firestore.updateDocument === 'function') {
      firestore.updateDocument(fullPath, updateData);
    } else {
      FirestoreApp.updateDocument(fullPath, updateData);
    }

    Logger.log('   ✅ settings/main محدّث');
  } catch (err) {
    Logger.log('   ❌ settings update: ' + err.message);
  }
}

// ═══════════════════════════════════════════════════════
//   Helpers
// ═══════════════════════════════════════════════════════

function extractLocationId(meeting) {
  if (meeting.LocationIds && Array.isArray(meeting.LocationIds) && meeting.LocationIds.length > 0) {
    return meeting.LocationIds[0];
  }
  if (meeting.LocationID) return meeting.LocationID;
  return '';
}

function normalizeStatus(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'active') return 'active';
  if (s === 'cancelled') return 'cancelled';
  if (s === 'inactive') return 'inactive';
  if (s === 'archived') return 'archived';
  return 'active';
}

// ═══════════════════════════════════════════════════════
//   Preview + Rollback
// ═══════════════════════════════════════════════════════

function previewMigration() {
  Logger.log('📊 Preview Migration');
  Logger.log('═══════════════════════════════════════════');

  const firestore = getFirestore();

  try {
    const meetings = firestore.getDocuments('meetings') || [];
    Logger.log(`📦 Meetings: ${meetings.length}`);
  } catch (e) {
    Logger.log('📦 Meetings: 0 (خطأ)');
  }

  try {
    const events = firestore.getDocuments('events') || [];
    Logger.log(`📦 Events: ${events.length}`);
  } catch (e) {
    Logger.log('📦 Events: 0 (فاضي)');
  }

  try {
    const locations = firestore.getDocuments('locations') || [];
    Logger.log(`📦 Locations: ${locations.length}`);
  } catch (e) {
    Logger.log('📦 Locations: 0 (فاضي)');
  }

  try {
    const attendance = firestore.getDocuments('attendance') || [];
    Logger.log(`📦 Attendance: ${attendance.length}`);
  } catch (e) {
    Logger.log('📦 Attendance: 0');
  }

  try {
    const eventTypes = firestore.getDocuments('eventTypes') || [];
    Logger.log(`📦 EventTypes: ${eventTypes.length}`);
  } catch (e) {
    Logger.log('📦 EventTypes: 0');
  }

  Logger.log('═══════════════════════════════════════════');
}

// ═══════════════════════════════════════════════════════
//   Rollback
// ═══════════════════════════════════════════════════════

function rollbackMigration() {
  Logger.log('⚠️ Rollback: سيتم حذف events اللي اتعمل لها migration');

  const firestore = getFirestore();
  const rawEvents = firestore.getDocuments('events') || [];

  let deleted = 0;
  for (const doc of rawEvents) {
    const evt = docToObject(doc);
    if (evt.MigratedFrom === 'meetings') {
      const evtId = getDocId(doc);
      try {
        const fullPath = 'events/' + evtId;
        if (typeof firestore.deleteDocument === 'function') {
          firestore.deleteDocument(fullPath);
        } else {
          FirestoreApp.deleteDocument(fullPath);
        }
        deleted++;
      } catch (e) {
        Logger.log(`❌ ${evtId}: ${e.message}`);
      }
    }
  }

  Logger.log(`✅ تم حذف ${deleted} event`);
}

// ═══════════════════════════════════════════════════════
//   Debug: عرض settings/main للتحقق من Locations
// ═══════════════════════════════════════════════════════

function debugSettingsMain() {
  const firestore = getFirestore();

  try {
    const settingsDoc = firestore.getDocument('settings/main');

    if (!settingsDoc) {
      Logger.log('❌ settings/main مش موجود');
      return;
    }

    Logger.log('📦 settings/main:');
    Logger.log(JSON.stringify(settingsDoc, null, 2));

    if (settingsDoc.fields) {
      Logger.log('\n⚡ الحقول الموجودة:');
      Object.keys(settingsDoc.fields).forEach(key => {
        const field = settingsDoc.fields[key];
        let value = '';

        if (field.stringValue !== undefined) value = field.stringValue;
        else if (field.integerValue !== undefined) value = field.integerValue;
        else if (field.booleanValue !== undefined) value = field.booleanValue;
        else if (field.arrayValue) value = `Array[${(field.arrayValue.values || []).length}]`;
        else if (field.mapValue) value = 'Map{...}';

        Logger.log(`   - ${key}: ${value}`);
      });
    }
  } catch (err) {
    Logger.log('❌ Error: ' + err.message);
  }
}
