          <span class="event-stat-label">إجمالي</span>
        </div>
        <div class="event-stat">
          <span class="event-stat-value">${eventsData.filter(e => String(e.Status || '').toLowerCase() === 'active').length}</span>
          <span class="event-stat-label">نشط</span>
