        </div>

        <!-- ═══ قواعد التسجيل ═══ -->
        <div class="modal-section">
          <h4 class="modal-section-title">⚙️ قواعد التسجيل</h4>

          <div class="location-mode-options">
            <label class="location-mode-option">
              <input type="radio" name="regScope" value="all" ${regScope === 'all' ? 'checked' : ''} />
