            <div class="locations-checkbox-list" id="regPeopleList"></div>
          </div>
        </div>

        <!-- ═══ الأماكن ═══ -->
        <div class="modal-section">
          <h4 class="modal-section-title">📍 الأماكن المسموحة</h4>

