  const notifPeopleList = document.getElementById('notifPeopleList');
  if (notifPeopleList) {
    fillPeopleList(notifPeopleList, []);
  }

  setTimeout(() => {
    const titleInput = document.getElementById('eventTitle');
    if (titleInput) titleInput.focus();
