function renderRequestsView(container) {
  container.innerHTML = `
    <div class="sch-requests-header">
      <h3>📨 طلبات النقل (${schRequests.length})</h3>
    </div>

    ${schRequests.length === 0 ? `
      <div class="sch-empty">
        <div class="sch-empty-icon">📨</div>
        <h3>لا يوجد طلبات</h3>
