          </div>
        </div>

        <div class="form-grid-2">
          <div class="form-row">
            <label>النطاق (بالأمتار)</label>
            <input type="number" id="locRadius" value="${loc?.Radius || 4}" min="1" max="1000" />
          </div>
          <div class="form-row">
