function renderMyRequestsView(container) {
  container.innerHTML = `
    <div class="sch-requests-header">
      <h3>📝 طلباتي (${schMyRequests.length})</h3>
    </div>

    ${schMyRequests.length === 0 ? `
      <div class="sch-empty">
        <div class="sch-empty-icon">📝</div>
