  if (!qrCode) {
    const randomPart = Math.random().toString(36).substring(2, 18);
    qrCode = 'ATTENDANCELOC' + randomPart;
  }

  const data = {
    Name: name,
    Lat: lat,
    Lng: lng,
    Radius: radius,
    Tolerance: tolerance,
    QRCode: qrCode,
    Status: status,
    Category: 'church',
    UpdatedAt: new Date().toISOString()
  };

  try {
    if (locId) {
      await updateDoc(doc(db, 'locations', locId), data);
      alert('✅ تم التعديل');
    } else {
      data.CreatedAt = new Date().toISOString();
