        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon">🎯</div>
        <div class="stat-info">
          <div class="stat-label">إجمالي الأحداث</div>
          <div class="stat-value">${data.stats.totalEvents}</div>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon">📈</div>
        <div class="stat-info">
          <div class="stat-label">نسبة الحضور</div>
          <div class="stat-value">${data.stats.attendanceRate}%</div>
        </div>
      </div>
