function normalizeSchedule(schedule) {
  if (!schedule || typeof schedule !== 'object') return {};

  const normalized = {};
  DAYS_OF_WEEK.forEach(d => {
    const dayData = schedule[d.value];
    normalized[d.value] = Array.isArray(dayData) ? dayData : [];
  });
  return normalized;
}

