/* ═══════════════════════════════════════════
   Dark Mode Styles — Enhanced
   ═══════════════════════════════════════════ */

/* ═══ Root Variables — Light (default) ═══ */
:root {
  --dm-transition: 0.25s ease;
}

/* ═══════════════════════════════════════════
   Dark Mode — Override Core Variables
   ⚡ ده أهم قسم — يخلي كل الملفات تتأثر تلقائيًا
   ═══════════════════════════════════════════ */

html[data-theme="dark"] {
  /* ═══ Core Variables (المستخدمة في كل الـCSS) ═══ */
  --bg: #0f172a !important;
  --card-bg: #1e293b !important;
  --text: #f1f5f9 !important;
  --text-muted: #cbd5e1 !important;
  --border: #334155 !important;

