  <!-- ═══ شاشة تعطيل الحساب ═══ -->
  <div id="disabledScreen" class="screen">
    <div class="denied-card">
      <div class="denied-icon">⛔</div>
      <h2>Account Disabled</h2>
      <p>حسابك معطل. تواصل مع المسؤول.</p>
      <button onclick="location.reload()" class="btn-primary">رجوع</button>
    </div>
  </div>

  <!-- ═══ Firebase SDK + Config ═══ -->
  <script type="module" src="js/firebase-config.js"></script>

  <!-- ═══ Pre-Auth Settings Loader ═══ -->
  <script type="module">
    import { db, COLLECTIONS, SETTINGS_DOC } from './js/firebase-config.js';
    import { doc, getDoc } from 'https://www.gstatic.com/firebasejs/10.13.0/firebase-firestore.js';

    // ⚡ القيم الافتراضية
    const DEFAULTS = {
      SystemName: 'QR Punch',
      OrganizationName: '',
      Subtitle: 'سجّل دخولك لتتبع حضورك',
      LogoUrl: '',
      BgImageUrl: '',
      FooterText: ''
    };

    async function loadPublicSettings() {
      let settings = { ...DEFAULTS };

      try {
        const settingsRef = doc(db, COLLECTIONS.SETTINGS, SETTINGS_DOC);
        const snap = await getDoc(settingsRef);

        if (snap.exists()) {
          const data = snap.data();
          settings = {
            SystemName: data.SystemName || DEFAULTS.SystemName,
            OrganizationName: data.OrganizationName || '',
            Subtitle: data.LoginSubtitle || DEFAULTS.Subtitle,
            LogoUrl: data.ThemeLogoUrl || '',
            BgImageUrl: data.ThemeBgImageUrl || '',
            FooterText: data.FooterText || ''
          };
        }
      } catch (err) {
        console.warn('⚠️ Could not load settings:', err.message);
      }

      applySettings(settings);
    }

    function applySettings(s) {
      // ═══ Title ═══
      document.title = s.SystemName || DEFAULTS.SystemName;

      // ═══ Logo ═══
      const brandLogo = document.getElementById('brandLogo');
      if (brandLogo) {
        if (s.LogoUrl) {
          brandLogo.innerHTML = `<img src="${s.LogoUrl}" alt="Logo" class="logo-image" />`;
          brandLogo.classList.add('has-image');
        } else {
          brandLogo.classList.remove('has-image');
        }
      }

      // ═══ Name ═══
      const brandName = document.getElementById('brandName');
      if (brandName) {
        // ⚡ اسم المؤسسة لو موجود، وإلا اسم النظام
        brandName.textContent = s.OrganizationName || s.SystemName || DEFAULTS.SystemName;
      }

      // ═══ Subtitle ═══
      const brandSubtitle = document.getElementById('brandSubtitle');
      if (brandSubtitle) {
        brandSubtitle.textContent = s.Subtitle || DEFAULTS.Subtitle;
      }

      // ═══ Background ═══
      const bgImage = document.getElementById('bgImage');
      if (bgImage && s.BgImageUrl) {
        bgImage.style.backgroundImage = `url('${s.BgImageUrl}')`;
        bgImage.classList.add('has-image');
      }

      // ═══ Footer ═══
      const pageFooter = document.getElementById('pageFooter');
      if (pageFooter) {
        if (s.FooterText) {
          pageFooter.textContent = s.FooterText;
        } else if (s.OrganizationName) {
          pageFooter.textContent = `© ${new Date().getFullYear()} ${s.OrganizationName}`;
        } else {
          pageFooter.textContent = '';
        }
      }
    }

    // ⚡ نفّذ بمجرد ما الصفحة تفتح
    loadPublicSettings();
  </script>

  <!-- ═══ Auth Logic ═══ -->
  <script type="module" src="js/auth.js"></script>
</body>
</html>
```

