.event-card-header {
  padding: 16px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.event-card-header h3 {
  font-size: 16px;
  color: var(--text);
  font-weight: 700;
  margin: 0;
  flex: 1;
  word-break: break-word;
  min-width: 0;
