.nav-item .nav-icon {
  font-size: 17px;
  width: 22px;
  text-align: center;
}

/* ═══ Sidebar Footer ═══ */
.sidebar-footer {
  padding: 16px;
  border-top: 1px solid rgba(255,255,255,0.08);
