  height: 18px;
  flex-shrink: 0;
}

/* ═══════════════════════════════════════════
   Main Content
   ═══════════════════════════════════════════ */

.main-content {
  flex: 1;
  margin-right: 260px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  /* ⚡ منع التشفيت */
  overflow-x: hidden;
  max-width: 100%;
  min-width: 0;
}

.topbar {
  background: var(--card-bg);
  border-bottom: 1px solid var(--border);
  padding: 16px 28px;
  display: flex;
  align-items: center;
  gap: 16px;
  position: sticky;
  top: 0;
  z-index: 50;
  /* ⚡ منع التشفيت */
  overflow-x: visible;
  max-width: 100%;
}

.topbar h1 {
  font-size: 20px;
  color: var(--text);
  font-weight: 700;
  flex-shrink: 0;
}

.menu-toggle {
  display: none;
  background: transparent;
  border: none;
  font-size: 22px;
  cursor: pointer;
  color: var(--text);
  flex-shrink: 0;
}

.topbar-right {
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
  min-width: 0;
}

.system-status {
  font-size: 20px;
  color: #22c55e;
  flex-shrink: 0;
}

.system-status.suspended {
  color: #ef4444;
}

/* ═══ Content ═══ */
.content-area {
  padding: 28px;
  flex: 1;
