  }

  /* Settings Actions */
  .settings-actions {
    flex-direction: column;
    gap: 10px;
    padding-top: 16px;
  }

  .settings-actions button {
    width: 100%;
    margin-top: 0;
    padding: 14px;
    font-size: 14px;
  }

  /* User Box */
  .user-name {
    font-size: 12px;
  }

  .user-role {
    font-size: 10px;
  }

