/* ═══════════════════════════════════════════
   Events Management Styles
   ═══════════════════════════════════════════ */

.events-container {
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
  overflow-x: hidden;
}

/* ═══ Header ═══ */
.events-header {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  min-width: 0;
}

/* ═══════════════════════════════════════════
   Filters
   ═══════════════════════════════════════════ */

.events-filters {
  display: flex;
  flex-wrap: nowrap;
  gap: 8px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 4px 8px 10px 8px;
  margin: 0 -8px;
  min-width: 0;
  width: 100%;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scroll-padding: 8px;
  scroll-snap-type: x proximity;
  overscroll-behavior-x: contain;
}

.events-filters::-webkit-scrollbar {
  height: 4px;
}

.events-filters::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

.events-filters::-webkit-scrollbar-track {
  background: transparent;
}

.filter-btn {
  padding: 8px 16px;
  border: 1px solid var(--border);
  background: var(--card-bg);
  color: var(--text-muted);
  border-radius: 20px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  white-space: nowrap;
  transition: all 0.2s;
  flex-shrink: 0;
