## ✅ الحل — 3 خطوات

### 📄 1. إضافة دالة لحذف الـTriggers في `Code.gs`

**افتح `Code.gs`** → ضيف الدالة دي في آخر الملف:

```javascript
// ═══════════════════════════════════════════════════════
//   ⚡ إلغاء كل الـTriggers (يدويًا)
// ═══════════════════════════════════════════════════════

function deleteAllSyncTriggers() {
  const triggers = ScriptApp.getProjectTriggers();
  let deleted = 0;
  let kept = 0;

  triggers.forEach(t => {
    const handler = t.getHandlerFunction();
    // ⚡ احذف triggers بتاعت الـSync والـAutoDeactivate
    if (handler === 'syncFormResponses' || handler === 'autoDeactivateOnceMeetings') {
      ScriptApp.deleteTrigger(t);
      deleted++;
      Logger.log(`🗑️ Deleted trigger: ${handler}`);
    } else {
      kept++;
      Logger.log(`⏭️ Kept trigger: ${handler}`);
    }
  });

  Logger.log(`\n✅ Total deleted: ${deleted}, kept: ${kept}`);
}

// ═══════════════════════════════════════════════════════
//   ⚡ عرض كل الـTriggers الحالية
