## 📄 4. إضافة دالة لإضافة Person للـIgnore List

**في نهاية `Code.gs`، ضيف:**

```javascript
// ═══════════════════════════════════════════════════════
//   ⚡ Ignore List Management
// ═══════════════════════════════════════════════════════

/**
 * ⚡ إضافة بريد لقائمة التجاهل
 * @param {string} email
 * @param {string} reason
 */
function addToIgnoreList(email, reason) {
  if (!email) {
    Logger.log('❌ Email required');
    return { ok: false, message: 'Email required' };
  }

  const emailLower = String(email).toLowerCase().trim();
  const firestore = getFirestore();

  // ⚡ استخدم البريد كـ ID (نتجنب التكرار)
  const safeId = emailLower.replace(/[^a-z0-9]/g, '_');

  const ignoreDoc = {
    Email: emailLower,
    Reason: reason || 'manual_delete',
    AddedAt: new Date().toISOString()
  };

  try {
    // ⚡ حاول تحديث أو إنشاء
    try {
      if (typeof firestore.updateDocument === 'function') {
        firestore.updateDocument(FIRESTORE_SYNC_IGNORES + '/' + safeId, ignoreDoc);
      } else {
        FirestoreApp.updateDocument(FIRESTORE_SYNC_IGNORES + '/' + safeId, ignoreDoc);
      }
      Logger.log(`✅ Updated in ignore list: ${emailLower}`);
    } catch (updateErr) {
      // ⚡ لو مش موجود، أنشئ
      if (typeof firestore.createDocument === 'function') {
        firestore.createDocument(FIRESTORE_SYNC_IGNORES, ignoreDoc, safeId);
      } else {
        FirestoreApp.createDocument(FIRESTORE_SYNC_IGNORES, ignoreDoc, safeId);
      }
      Logger.log(`✅ Added to ignore list: ${emailLower}`);
    }

    return { ok: true, email: emailLower };
  } catch (err) {
    Logger.log('❌ addToIgnoreList error: ' + err.message);
    return { ok: false, message: err.message };
  }
}

/**
 * ⚡ إزالة بريد من قائمة التجاهل
 */
function removeFromIgnoreList(email) {
  if (!email) return { ok: false };

  const emailLower = String(email).toLowerCase().trim();
  const safeId = emailLower.replace(/[^a-z0-9]/g, '_');
  const firestore = getFirestore();

  try {
    if (typeof firestore.deleteDocument === 'function') {
      firestore.deleteDocument(FIRESTORE_SYNC_IGNORES + '/' + safeId);
    } else {
      FirestoreApp.deleteDocument(FIRESTORE_SYNC_IGNORES + '/' + safeId);
    }
    Logger.log(`✅ Removed from ignore list: ${emailLower}`);
    return { ok: true, email: emailLower };
  } catch (err) {
    Logger.log('❌ removeFromIgnoreList error: ' + err.message);
    return { ok: false, message: err.message };
  }
}

/**
 * ⚡ عرض كل قائمة التجاهل
 */
function listIgnoreList() {
  const firestore = getFirestore();
  try {
    const rawIgnores = firestore.getDocuments(FIRESTORE_SYNC_IGNORES) || [];
    const ignoreList = rawIgnores.map(docToObject);
    Logger.log(`📋 Ignore list: ${ignoreList.length} entries`);
    ignoreList.forEach(i => {
      Logger.log(`   - ${i.Email} | ${i.Reason || 'no reason'} | ${i.AddedAt || ''}`);
    });
  } catch (err) {
    Logger.log('❌ listIgnoreList error: ' + err.message);
  }
}
```

