function doGet(e) {
  try {
    const action = e.parameter.action;

    if (action === 'sync') {
      const result = syncFormResponses();
      return jsonResponse(result);
    }

    if (action === 'autoDeactivate') {
      const result = autoDeactivateOnceMeetings();
      return jsonResponse(result);
    }

    if (action === 'listIgnores') {
      const result = listIgnoreList();
      return jsonResponse({ ok: true, list: result });
    }

    return jsonResponse({ ok: true, message: 'Sync service is running' });
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function doPost(e) {
  try {
    let action = '';
    let body = {};

    if (e.postData && e.postData.contents) {
      try {
        body = JSON.parse(e.postData.contents);
        action = body.action || '';
      } catch (parseErr) {
        action = e.parameter.action || '';
      }
    } else {
      action = e.parameter.action || '';
    }

    if (action === 'sync') {
      const result = syncFormResponses();
      return jsonResponse(result);
    }

    if (action === 'autoDeactivate') {
      const result = autoDeactivateOnceMeetings();
      return jsonResponse(result);
    }

    if (action === 'addToIgnoreList') {
      const result = addToIgnoreList(body.email || '', body.reason || '');
      return jsonResponse(result);
    }

    if (action === 'removeFromIgnoreList') {
      const result = removeFromIgnoreList(body.email || '');
      return jsonResponse(result);
    }

    if (action === 'listIgnores') {
      const result = listIgnoreList();
      return jsonResponse({ ok: true, list: result });
    }

    if (action === 'cleanIgnoreList') {
      cleanIgnoreList();
      return jsonResponse({ ok: true });
    }

    return jsonResponse({ ok: true, message: 'Sync service is running' });
  } catch (err) {
    return jsonResponse({ ok: false, message: err.message });
  }
}

function jsonResponse(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}
