  const isEdit = !!template;

  modal.innerHTML = `
    <div class="modal-content modal-large" style="max-width:900px;max-height:90vh;display:flex;flex-direction:column;">
      <div class="modal-header">
        <h2>${isEdit ? '✏️ تعديل نمط' : '➕ نمط جديد'}</h2>
